import React, { useMemo, useState, useRef, useEffect } from 'react';
import { useData } from '../../hooks/useDataContext';
import { downloadAsCSV } from '../../services/csvExport';
import { PersonStatus, AttendanceStatus } from '../../types';
import { Table, SortConfig, Column } from '../common/Table';
import { Pagination } from '../common/Pagination';
import { ListItemCard } from '../common/ListItemCard';
import { Button } from '../common/Button';
import { ICONS } from '../../constants';
import { PrintableAttendanceReport, AttendanceReportData } from './PrintableAttendanceReport';

const ITEMS_PER_PAGE = 15;

interface AttendanceReportTabProps { 
    startDate: string; 
    endDate: string; 
    classFilter: string; 
}

export const AttendanceReportTab: React.FC<AttendanceReportTabProps> = ({ startDate, endDate, classFilter }) => {
    const { state } = useData();
    const { students, classes, attendance } = state;
    const [searchQuery, setSearchQuery] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [sortConfig, setSortConfig] = useState<SortConfig<AttendanceReportData> | null>({ key: 'attendanceCount', direction: 'descending' });
    const reportRef = useRef<HTMLDivElement>(null);
    const [isExportingImage, setIsExportingImage] = useState(false);

    const reportData = useMemo(() => {
        let relevantStudents = students.filter(s => s.status === PersonStatus.ACTIVE);
        if (classFilter !== 'all') {
            const classStudentIds = new Set(classes.find(c => c.id === classFilter)?.studentIds || []);
            relevantStudents = relevantStudents.filter(s => classStudentIds.has(s.id));
        }

        if (searchQuery) {
            const lowerQuery = searchQuery.toLowerCase();
            relevantStudents = relevantStudents.filter(s => s.name.toLowerCase().includes(lowerQuery) || s.id.toLowerCase().includes(lowerQuery));
        }

        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (classFilter === 'all' || a.classId === classFilter) &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );

        const attendanceCounts = new Map<string, number>();
        periodAttendance.forEach(a => {
            attendanceCounts.set(a.studentId, (attendanceCounts.get(a.studentId) || 0) + 1);
        });

        return relevantStudents.map(student => ({
            id: student.id,
            name: student.name,
            classNames: classes.filter(c => c.studentIds.includes(student.id)).map(c => c.name).join(', '),
            attendanceCount: attendanceCounts.get(student.id) || 0
        }));

    }, [students, classes, attendance, startDate, endDate, classFilter, searchQuery]);

    const sortedData = useMemo(() => {
        let sortableItems = [...reportData];
        if (sortConfig !== null) {
            const getLastName = (fullName: string) => {
                if (!fullName) return '';
                const parts = fullName.trim().split(/\s+/);
                return parts[parts.length - 1];
            };

            sortableItems.sort((a, b) => {
                if (sortConfig.key === 'name') {
                    const lastNameA = getLastName(a.name);
                    const lastNameB = getLastName(b.name);

                    const lastNameComparison = lastNameA.localeCompare(lastNameB, 'vi');

                    if (lastNameComparison !== 0) {
                        return sortConfig.direction === 'ascending' ? lastNameComparison : -lastNameComparison;
                    }

                    // If last names are the same, sort by full name for stability
                    const fullNameComparison = a.name.localeCompare(b.name, 'vi');
                    return sortConfig.direction === 'ascending' ? fullNameComparison : -fullNameComparison;
                }

                // Fallback for other columns
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];

                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [reportData, sortConfig]);

    const totalPages = Math.ceil(sortedData.length / ITEMS_PER_PAGE);
    const paginatedData = sortedData.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, classFilter, startDate, endDate]);

    const handleSort = (key: keyof AttendanceReportData) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setSortConfig({ key, direction });
    };

    const handleExport = () => {
        downloadAsCSV(sortedData, {
            id: 'Mã HV',
            name: 'Họ tên',
            classNames: 'Các lớp học',
            attendanceCount: `Số buổi có mặt (${startDate} - ${endDate})`
        }, `BaoCaoChuyenCan_${startDate}_${endDate}.csv`);
    };

    const handleExportImage = () => {
        if (reportRef.current && window.html2canvas) {
            setIsExportingImage(true);
            window.html2canvas(reportRef.current, { scale: 2, useCORS: true }).then((canvas: any) => {
                const link = document.createElement('a');
                link.download = `BaoCaoChuyenCan_${startDate}_${endDate}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
            }).catch((err: any) => {
                console.error("Lỗi xuất ảnh:", err);
            }).finally(() => {
                setIsExportingImage(false);
            });
        }
    };

    const columns: Column<AttendanceReportData>[] = [
        { header: 'Mã HV', accessor: 'id', sortable: true },
        { header: 'Họ tên', accessor: 'name', sortable: true },
        { header: 'Các lớp học', accessor: 'classNames', sortable: false },
        { header: 'Số buổi có mặt', accessor: 'attendanceCount', sortable: true },
    ];

    return (
        <>
            <div ref={reportRef} style={{ position: 'absolute', left: '-9999px', width: '210mm' }}>
                <PrintableAttendanceReport
                    data={sortedData}
                    title={`Thống kê Chuyên cần (${startDate} đến ${endDate})`}
                />
            </div>
            <div className="card-base">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                    <h2 className="text-xl font-semibold">Thống kê Chuyên cần</h2>
                    <div className="flex flex-wrap gap-2">
                        <Button onClick={handleExportImage} variant="secondary" isLoading={isExportingImage}>
                            {ICONS.download} Xuất ảnh
                        </Button>
                        <Button onClick={handleExport} variant="secondary">{ICONS.export} Xuất CSV</Button>
                    </div>
                </div>
                <input 
                    type="text"
                    placeholder="Tìm học viên..."
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    className="form-input mb-4"
                />
                <div className="hidden md:block">
                    <Table
                        columns={columns}
                        data={paginatedData}
                        sortConfig={sortConfig}
                        onSort={handleSort}
                    />
                </div>
                <div className="md:hidden space-y-4">
                     {paginatedData.map(item => (
                        <ListItemCard
                            key={item.id}
                            title={item.name}
                            details={[
                                { label: 'Mã HV', value: item.id },
                                { label: `Số buổi có mặt`, value: <span className="font-bold text-lg text-primary">{item.attendanceCount}</span> }
                            ]}
                        />
                    ))}
                </div>
                 {paginatedData.length > 0 && (
                    <Pagination
                        currentPage={currentPage}
                        totalPages={totalPages}
                        onPageChange={setCurrentPage}
                        totalItems={sortedData.length}
                        itemsPerPage={ITEMS_PER_PAGE}
                    />
                )}
            </div>
        </>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useData } from '../../hooks/useDataContext';
import { Table, SortConfig, Column } from '../common/Table';
import { Button } from '../common/Button';
import { ICONS } from '../../constants';
import { Transaction, TransactionType, Class, Student } from '../../types';
import { downloadAsCSV } from '../../services/csvExport';
import { Pagination } from '../common/Pagination';
import { ListItemCard } from '../common/ListItemCard';

const ITEMS_PER_PAGE = 15;

interface TransactionWithDetails extends Transaction {
    studentName: string;
    classNames: string;
}

interface TransactionHistoryReportTabProps {
    startDate: string;
    endDate: string;
    classFilter: string;
}

const transactionTypeMap: Record<TransactionType, string> = {
    [TransactionType.INVOICE]: 'Hóa đơn',
    [TransactionType.PAYMENT]: 'Thanh toán',
    [TransactionType.ADJUSTMENT_CREDIT]: 'Điều chỉnh Tăng',
    [TransactionType.ADJUSTMENT_DEBIT]: 'Điều chỉnh Giảm',
};

export const TransactionHistoryReportTab: React.FC<TransactionHistoryReportTabProps> = ({ startDate, endDate, classFilter }) => {
    const { state } = useData();
    const { transactions, students, classes } = state;
    const [searchQuery, setSearchQuery] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [sortConfig, setSortConfig] = useState<SortConfig<TransactionWithDetails> | null>({ key: 'date', direction: 'descending' });

    const reportData = useMemo(() => {
        let relevantTransactions = transactions.filter(t => t.date >= startDate && t.date <= endDate);

        // Fix: Explicitly type the studentMap to ensure correct type inference from .get()
        const studentMap: Map<string, Student> = new Map(students.map((s: Student) => [s.id, s]));
        const studentClassMap = new Map<string, string[]>();
        students.forEach((student: Student) => {
            const enrolledClasses = (classes as Class[])
                .filter((c: Class) => c.studentIds.includes(student.id))
                .map((c: Class) => c.name);
            studentClassMap.set(student.id, enrolledClasses);
        });

        if (classFilter !== 'all') {
            const classStudentIds = new Set(classes.find((c: Class) => c.id === classFilter)?.studentIds || []);
            relevantTransactions = relevantTransactions.filter(t => classStudentIds.has(t.studentId));
        }

        let processedData: TransactionWithDetails[] = relevantTransactions.map(t => ({
            ...t,
            studentName: studentMap.get(t.studentId)?.name || 'N/A',
            classNames: studentClassMap.get(t.studentId)?.join(', ') || 'N/A',
        }));

        if (searchQuery) {
            const lowerQuery = searchQuery.toLowerCase();
            processedData = processedData.filter(t => t.studentName.toLowerCase().includes(lowerQuery));
        }

        return processedData;

    }, [transactions, students, classes, startDate, endDate, classFilter, searchQuery]);

    const sortedData = useMemo(() => {
        let sortableItems = [...reportData];
        if (sortConfig !== null) {
            sortableItems.sort((a, b) => {
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];

                if (aValue == null || bValue == null) return 0;

                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;

                // If primary sort keys are equal (e.g., same date), sort by ID descending
                // to ensure the newest transaction is always on top.
                return b.id.localeCompare(a.id);
            });
        }
        return sortableItems;
    }, [reportData, sortConfig]);

    const totalPages = Math.ceil(sortedData.length / ITEMS_PER_PAGE);
    const paginatedData = sortedData.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, classFilter, startDate, endDate]);

    const handleSort = (key: keyof TransactionWithDetails) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setSortConfig({ key, direction });
    };

    const handleExport = () => {
        const dataToExport = sortedData.map(t => ({
            date: t.date,
            studentName: t.studentName,
            classNames: t.classNames,
            description: t.description,
            type: transactionTypeMap[t.type],
            amount: t.amount,
        }));
        downloadAsCSV(dataToExport, {
            date: 'Ngày',
            studentName: 'Họ tên',
            classNames: 'Các lớp học',
            description: 'Diễn giải',
            type: 'Loại Giao dịch',
            amount: `Số tiền`
        }, `LichSuGiaoDich_${startDate}_${endDate}.csv`);
    };

    const columns: Column<TransactionWithDetails>[] = [
        { header: 'Ngày', accessor: 'date', sortable: true },
        { header: 'Họ tên', accessor: 'studentName', sortable: true },
        { header: 'Lớp học', accessor: 'classNames' },
        { header: 'Diễn giải', accessor: 'description' },
        { header: 'Loại', accessor: (item) => transactionTypeMap[item.type], sortable: true, sortKey: 'type' },
        { header: 'Số tiền', accessor: (item) => (
            <span className={item.amount >= 0 ? 'text-green-600 dark:text-green-400 font-semibold' : 'text-red-600 dark:text-red-400 font-semibold'}>
                {item.amount.toLocaleString('vi-VN')} ₫
            </span>
        ), sortable: true, sortKey: 'amount' },
    ];

    return (
        <div className="card-base">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                <h2 className="text-xl font-semibold">Lịch sử Giao dịch</h2>
                <Button onClick={handleExport} variant="secondary">{ICONS.export} Xuất CSV</Button>
            </div>
            <input 
                type="text"
                placeholder="Tìm theo tên học viên..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                className="form-input mb-4"
            />
            <div className="hidden md:block">
                <Table
                    columns={columns}
                    data={paginatedData}
                    sortConfig={sortConfig}
                    onSort={handleSort}
                />
            </div>
            <div className="md:hidden space-y-4">
                 {paginatedData.map(item => (
                    <ListItemCard
                        key={item.id}
                        title={item.studentName}
                        details={[
                            { label: 'Ngày', value: item.date },
                            { label: 'Diễn giải', value: item.description },
                            { label: 'Số tiền', value: (
                                <span className={item.amount >= 0 ? 'text-green-600 dark:text-green-400 font-semibold' : 'text-red-600 dark:text-red-400 font-semibold'}>
                                    {item.amount.toLocaleString('vi-VN')} ₫
                                </span>
                            )},
                        ]}
                    />
                ))}
            </div>
             {paginatedData.length > 0 && (
                <Pagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setCurrentPage}
                    totalItems={sortedData.length}
                    itemsPerPage={ITEMS_PER_PAGE}
                />
            )}
        </div>
    );
};

import React, { useMemo, useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useAuth } from '../hooks/useAuth';
import { Card } from '../components/common/Card';
import { ICONS } from '../constants';
import { UserRole } from '../types';
import { UnpaidStudentsReport } from '../components/finance/UnpaidStudentsReport';
import { TeacherPayrollTab } from '../components/finance/TeacherPayrollTab';
import { PayrollTab } from '../components/finance/PayrollTab';
import { InvoicesTab } from '../components/finance/InvoicesTab';
import { IncomeTab } from '../components/finance/IncomeTab';
import { ExpenseTab } from '../components/finance/ExpenseTab';

declare global {
    interface Window {
        html2canvas: any;
    }
}

type FinanceTab = 'overview' | 'debt_report' | 'invoices' | 'payroll' | 'income' | 'expenses' | 'my_payroll';

const OverviewTab: React.FC<{startDate: string, endDate: string}> = ({startDate, endDate}) => {
    const { state } = useData();

    const financialSummary = useMemo(() => {
        // 1. Doanh thu ghi nhận (Accrual Revenue): Từ hóa đơn đã tạo trong khoảng thời gian
        const accrualRevenue = state.invoices
            .filter(i => i.generatedDate >= startDate && i.generatedDate <= endDate && i.status !== 'CANCELLED')
            .reduce((sum, i) => sum + i.amount, 0);

        // 2. Thực thu từ Học phí (Cash Tuition): Từ giao dịch thanh toán thực tế trong khoảng thời gian
        const tuitionCollected = state.transactions
            .filter(t => t.date >= startDate && t.date <= endDate && t.amount > 0)
            .reduce((sum, t) => sum + t.amount, 0);

        // 3. Thực thu từ Nguồn khác (Other Income) trong khoảng thời gian
        const otherIncome = state.income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .reduce((sum, i) => sum + i.amount, 0);

        // Tổng thực thu (Cash Revenue)
        const cashRevenue = tuitionCollected + otherIncome;

        // 4. Tổng chi phí (Total Expenses): Bao gồm lương và chi phí khác trong khoảng thời gian
        const totalExpenses = state.expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .reduce((sum, e) => sum + e.amount, 0);

        // 5. Công nợ & Số dư ví (Tính tại thời điểm hiện tại, không theo kỳ lịch sử)
        const totalReceivables = state.students
            .filter(s => s.balance < 0)
            .reduce((sum, s) => sum + s.balance, 0);

        const totalCredit = state.students
            .filter(s => s.balance > 0)
            .reduce((sum, s) => sum + s.balance, 0);

        return {
            accrualRevenue,
            cashRevenue,
            totalExpenses,
            cashFlow: cashRevenue - totalExpenses,
            totalReceivables: Math.abs(totalReceivables),
            totalCredit,
            otherIncome
        };
    }, [state.invoices, state.transactions, state.expenses, state.students, state.income, startDate, endDate]);

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card title={`Doanh thu ghi nhận (Hóa đơn)`} value={`${financialSummary.accrualRevenue.toLocaleString('vi-VN')} ₫`} icon={ICONS.reports} color="text-blue-600 dark:text-blue-400" />
                <Card 
                    title={`Tổng Thực thu (Tiền mặt)`} 
                    value={`${financialSummary.cashRevenue.toLocaleString('vi-VN')} ₫`} 
                    icon={ICONS.finance} 
                    color="text-green-600 dark:text-green-400" 
                />
                <Card 
                    title={`Dòng tiền (Thu - Chi)`} 
                    value={`${financialSummary.cashFlow.toLocaleString('vi-VN')} ₫`} 
                    icon={ICONS.dashboard} 
                    color={financialSummary.cashFlow >= 0 ? "text-teal-600 dark:text-teal-400" : "text-red-600 dark:text-red-400"} 
                />
            </div>
             <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <Card title={`Tổng chi phí`} value={`${financialSummary.totalExpenses.toLocaleString('vi-VN')} ₫`} icon={ICONS.logout} color="text-orange-600 dark:text-orange-400" />
                <Card title={`Thu khác`} value={`${financialSummary.otherIncome.toLocaleString('vi-VN')} ₫`} icon={ICONS.plus} color="text-cyan-600 dark:text-cyan-400" />
                <Card title={`Tổng nợ phải thu (Hiện tại)`} value={`${financialSummary.totalReceivables.toLocaleString('vi-VN')} ₫`} icon={ICONS.students} color="text-red-500 dark:text-red-400" />
                <Card title={`Số dư ví học viên (Hiện tại)`} value={`${financialSummary.totalCredit.toLocaleString('vi-VN')} ₫`} icon={ICONS.checkCircle} color="text-indigo-500 dark:text-indigo-400" />
            </div>
        </div>
    )
}

export const FinanceScreen: React.FC = () => {
    const { role } = useAuth();
    const location = useLocation();

    const [activeTab, setActiveTab] = useState<FinanceTab>('overview');

    // Default to current month
    const today = new Date();
    const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
    const endOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().split('T')[0];

    const [startDate, setStartDate] = useState(startOfMonth);
    const [endDate, setEndDate] = useState(endOfMonth);

    useEffect(() => {
        if (location.state?.defaultTab) {
            setActiveTab(location.state.defaultTab);
        }
    }, [location.state]);

    const setPeriod = (type: 'this_month' | 'last_month' | 'this_year') => {
        const now = new Date();
        let start, end;
        switch (type) {
            case 'this_month':
                start = new Date(now.getFullYear(), now.getMonth(), 1);
                end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
                break;
            case 'last_month':
                start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
                end = new Date(now.getFullYear(), now.getMonth(), 0);
                break;
            case 'this_year':
                start = new Date(now.getFullYear(), 0, 1);
                end = new Date(now.getFullYear(), 11, 31);
                break;
        }
        setStartDate(start.toISOString().split('T')[0]);
        setEndDate(end.toISOString().split('T')[0]);
    };


    const TabButton: React.FC<{ tabId: FinanceTab; children: React.ReactNode, hidden?: boolean }> = ({ tabId, children, hidden }) => {
        if (hidden) return null;
        return (
            <button
                onClick={() => setActiveTab(tabId)}
                className={`px-3 py-2 text-sm font-medium rounded-md transition-colors ${activeTab === tabId ? 'bg-primary text-white shadow-sm' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
            >
                {children}
            </button>
        );
    }

    const canManageFullFinance = role === UserRole.ADMIN || role === UserRole.ACCOUNTANT;

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold">Quản lý Tài chính</h1>

            <div className="flex flex-wrap items-center gap-2 border-b dark:border-gray-700 pb-2">
                <TabButton tabId="overview" hidden={!canManageFullFinance}>Tổng quan</TabButton>
                <TabButton tabId="invoices" hidden={!canManageFullFinance}>Hóa đơn</TabButton>
                <TabButton tabId="debt_report" hidden={!canManageFullFinance}>Công nợ</TabButton>
                <TabButton tabId="income" hidden={!canManageFullFinance}>Thu khác</TabButton>
                <TabButton tabId="expenses" hidden={!canManageFullFinance}>Chi phí</TabButton>
                <TabButton tabId="payroll" hidden={!canManageFullFinance}>Bảng lương</TabButton>
                <TabButton tabId="my_payroll" hidden={role !== UserRole.TEACHER}>Bảng lương của tôi</TabButton>
            </div>

            {(activeTab === 'overview') && (
                <div className="flex flex-col lg:flex-row items-start lg:items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-lg border dark:border-slate-700">
                    <div className="flex items-center gap-2 flex-wrap">
                        <div className="flex items-center gap-2">
                            <span className="text-sm font-medium whitespace-nowrap">Từ:</span>
                            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="text-sm font-medium whitespace-nowrap">Đến:</span>
                            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                        </div>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => setPeriod('this_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng này</button>
                        <button onClick={() => setPeriod('last_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng trước</button>
                        <button onClick={() => setPeriod('this_year')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Năm nay</button>
                    </div>
                </div>
            )}

            <div>
                {activeTab === 'overview' && canManageFullFinance && <OverviewTab startDate={startDate} endDate={endDate} />}
                {activeTab === 'invoices' && canManageFullFinance && <InvoicesTab />}
                {activeTab === 'debt_report' && canManageFullFinance && <UnpaidStudentsReport />}
                {activeTab === 'income' && canManageFullFinance && <IncomeTab />}
                {activeTab === 'expenses' && canManageFullFinance && <ExpenseTab />}
                {activeTab === 'payroll' && canManageFullFinance && <PayrollTab period={'this_month'} />}
                {activeTab === 'my_payroll' && role === UserRole.TEACHER && <TeacherPayrollTab />}
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../hooks/useDataContext';
import { Card } from '../components/common/Card';
import { ICONS } from '../constants';
import { LineChart } from '../components/common/LineChart';
import { PieChart } from '../components/common/PieChart';
import { AttendanceStatus, FeeType, TransactionType } from '../types';
import { ReportDetailModal } from '../components/reports/ReportDetailModal';
import { AttendanceReportTab } from '../components/reports/AttendanceReportTab';
import { TransactionHistoryReportTab } from '../components/reports/TransactionHistoryReportTab';

const today = new Date();
const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
const endOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().split('T')[0];

type ReportTab = 'overview' | 'attendance' | 'transactions';

export const ReportsScreen: React.FC = () => {
    const { state } = useData();
    const { students, classes, invoices, income, expenses, attendance, transactions } = state;

    // State cho khoảng thời gian tùy chỉnh
    const [startDate, setStartDate] = useState(startOfMonth);
    const [endDate, setEndDate] = useState(endOfMonth);

    const [classFilter, setClassFilter] = useState('all');
    const [activeTab, setActiveTab] = useState<ReportTab>('overview');
    const [detailModal, setDetailModal] = useState<{
        isOpen: boolean;
        title: string;
        items: { description: string; date: string; amount?: number; type?: 'credit' | 'debit' }[];
    }>({ isOpen: false, title: '', items: [] });

    const filteredStudentIds = useMemo(() => {
        if (classFilter === 'all') {
            return null; // Represents all students
        }
        const selectedClass = classes.find(c => c.id === classFilter);
        return new Set(selectedClass?.studentIds || []);
    }, [classFilter, classes]);

    // Helper: Nhóm dữ liệu cho biểu đồ đường
    // Nếu khoảng thời gian <= 31 ngày -> Nhóm theo ngày
    // Nếu khoảng thời gian > 31 ngày -> Nhóm theo tháng
    const trendAnalytics = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        const isDaily = diffDays <= 32;

        const dataMap = new Map<string, { revenue: number, expense: number }>();

        // Init map keys
        if (isDaily) {
            let loop = new Date(start);
            while (loop <= end) {
                const key = loop.toISOString().split('T')[0]; // YYYY-MM-DD
                dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setDate(loop.getDate() + 1);
            }
        } else {
            let loop = new Date(start);
            // Set to first day of month to avoid skipping months
            loop.setDate(1); 
            while (loop <= end) {
                const key = loop.toISOString().slice(0, 7); // YYYY-MM
                if (!dataMap.has(key)) dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setMonth(loop.getMonth() + 1);
            }
        }

        // Fill Data
        // 1. Revenue from Transactions (Tuition)
        transactions.forEach(t => {
            if (t.date >= startDate && t.date <= endDate) {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;

                if (isPayment && isNotRefund && t.amount > 0 && studentIsInClass) {
                    const key = isDaily ? t.date : t.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += t.amount;
                    }
                }
            }
        });

        // 2. Revenue from Other Income (Only if not filtering by class)
        if (!filteredStudentIds) {
            income.forEach(inc => {
                if (inc.date >= startDate && inc.date <= endDate) {
                    const key = isDaily ? inc.date : inc.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += inc.amount;
                    }
                }
            });
        }

        // 3. Expenses (Global)
        expenses.forEach(exp => {
            if (exp.date >= startDate && exp.date <= endDate) {
                const key = isDaily ? exp.date : exp.date.slice(0, 7);
                if (dataMap.has(key)) {
                    dataMap.get(key)!.expense += exp.amount;
                }
            }
        });

        // Convert Map to Array for Chart
        return Array.from(dataMap.entries()).map(([label, values]) => {
            // Format label
            let displayLabel = label;
            if (isDaily) {
                const [y, m, d] = label.split('-');
                displayLabel = `${d}/${m}`;
            } else {
                const [y, m] = label.split('-');
                displayLabel = `T${m}/${y}`;
            }
            return {
                label: displayLabel,
                values: [values.revenue, values.expense]
            };
        });

    }, [transactions, income, expenses, startDate, endDate, filteredStudentIds]);


    // KPIs trong khoảng thời gian đã chọn
    const periodKpiData = useMemo(() => {
        const tuitionFeesCollected = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithinPeriod = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithinPeriod && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .reduce((sum, t) => sum + t.amount, 0);

        const otherIncome = income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .reduce((sum, i) => sum + i.amount, 0);

        // Revenue depends on filter
        const totalRevenue = tuitionFeesCollected + (filteredStudentIds ? 0 : otherIncome);

        // Expenses are always global
        const totalExpense = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .reduce((sum, e) => sum + e.amount, 0);

        let provisionalTuitionFee = 0;

        // Count attendance within the period
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );

        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const studentsForProvisional = students.filter(s => 
            (s.status === 'ACTIVE') && 
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        );
        const activeStudentIds = new Set(studentsForProvisional.map(s => s.id));

        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudentIds.has(id));

            if (c.fee.type === FeeType.MONTHLY) {
                // Với học phí tháng, ta ước tính theo tỷ lệ số tháng trong khoảng thời gian chọn? 
                // Để đơn giản và chính xác, ta chỉ tính full nếu khoảng thời gian bao trùm ít nhất 1 tháng?
                // Tạm thời logic cũ: chỉ cộng fee nếu active. Cải thiện: Nhân với số tháng trong range?
                // Logic hiện tại: Tính 1 lần phí tháng cho KPI đơn giản.
                provisionalTuitionFee += activeStudentsInClass.length * c.fee.amount;
            } else if (c.fee.type === FeeType.PER_SESSION) {
                activeStudentsInClass.forEach(studentId => {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    provisionalTuitionFee += attendedSessions * c.fee.amount;
                });
            }
        });

        // New Students within period
        const newStudents = students.filter(s => 
            s.createdAt >= startDate && s.createdAt <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        ).length;

        return {
            totalRevenue,
            totalExpense: filteredStudentIds ? 0 : totalExpense,
            profit: totalRevenue - (filteredStudentIds ? 0 : totalExpense),
            tuitionFeesCollected,
            provisionalTuitionFee,
            newStudents
        };
    }, [invoices, income, expenses, students, classes, attendance, transactions, startDate, endDate, classFilter, filteredStudentIds]);


    const revenueByClass = useMemo(() => {
        const revenueMap = new Map<string, number>();
        const paidInvoices = invoices.filter(inv => 
            inv.status === 'PAID' && 
            inv.paidDate && inv.paidDate >= startDate && inv.paidDate <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(inv.studentId) : true)
        );

        paidInvoices.forEach(invoice => {
            const studentClasses = classes.filter(c => (c.studentIds || []).includes(invoice.studentId));
            if (studentClasses.length > 0) {
                const amountPerClass = invoice.amount / studentClasses.length;
                studentClasses.forEach(c => {
                    revenueMap.set(c.name, (revenueMap.get(c.name) || 0) + amountPerClass);
                });
            }
        });

        let finalData = Array.from(revenueMap.entries())
            .map(([label, value]) => ({ label, value, color: '' }))
            .sort((a,b) => b.value - a.value);

        if (classFilter !== 'all') {
            finalData = finalData.filter(d => {
                const cls = classes.find(c => c.id === classFilter);
                return cls?.name === d.label;
            });
        }

        return finalData;

    }, [invoices, classes, startDate, endDate, classFilter, filteredStudentIds]);

    // --- Detail Modal Handlers ---

    const handleShowProvisionalTuitionDetails = () => {
        const items: { description: string; date: string; amount: number; type: 'credit' }[] = [];

        // Logic tương tự periodKpiData nhưng push vào items
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );
        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const activeStudents = students.filter(s => s.status === 'ACTIVE' && (filteredStudentIds ? filteredStudentIds.has(s.id) : true));
        const studentMap = new Map(students.map(s => [s.id, s.name]));
        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudents.some(s => s.id === id));
            activeStudentsInClass.forEach(studentId => {
                const studentName = studentMap.get(studentId) || 'Không rõ';
                if (c.fee.type === FeeType.MONTHLY) {
                    // For monthly fee, check if attended at least once or just list it as monthly due
                    const key = `${studentId}-${c.id}`;
                    if (attendanceCountMap.has(key)) {
                         items.push({
                            description: `[${c.name}] ${studentName} (HP tháng)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: c.fee.amount,
                            type: 'credit'
                        });
                    }
                } else if (c.fee.type === FeeType.PER_SESSION) {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    if (attendedSessions > 0) {
                        items.push({
                            description: `[${c.name}] ${studentName} (${attendedSessions} buổi)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: attendedSessions * c.fee.amount,
                            type: 'credit'
                        });
                    }
                }
            });
        });

        setDetailModal({
            isOpen: true,
            title: `Chi tiết Học phí Tạm tính`,
            items: items.sort((a,b) => a.description.localeCompare(b.description))
        });
    };

    const handleShowRevenueDetails = () => {
        const tuitionItems = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithin = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithin && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .map(t => {
                const studentName = students.find(s => s.id === t.studentId)?.name || 'Không rõ';
                return {
                    description: `[HP] ${studentName} - ${t.description}`,
                    date: t.date,
                    amount: t.amount,
                    type: 'credit' as const
                };
            });

        const otherIncomeItems = classFilter === 'all' ? income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .map(i => ({
                description: `[Thu khác] ${i.description}`,
                date: i.date,
                amount: i.amount,
                type: 'credit' as const
            })) : [];

        // Sort descending by date (Newest first)
        const allItems = [...tuitionItems, ...otherIncomeItems].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setDetailModal({ isOpen: true, title: `Chi tiết Doanh thu`, items: allItems });
    };

    const handleShowExpenseDetails = () => {
        const items = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .map(e => ({
                description: e.description,
                date: e.date,
                amount: e.amount,
                type: 'debit' as const
            }));

        // Sort descending by date (Newest first)
        items.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

        setDetailModal({ isOpen: true, title: `Chi tiết Chi phí`, items: items });
    };

    const handleShowNewStudentsDetails = () => {
        const items = students
            .filter(s => s.createdAt >= startDate && s.createdAt <= endDate && (filteredStudentIds ? filteredStudentIds.has(s.id) : true))
            .map(s => ({
                description: s.name,
                date: s.createdAt,
            }));

        // Sort descending by date (Newest first)
        items.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

        setDetailModal({ isOpen: true, title: `Chi tiết Học viên mới`, items: items });
    };

    const setPeriod = (type: 'this_month' | 'last_month' | 'this_year') => {
        const now = new Date();
        let start, end;
        switch (type) {
            case 'this_month':
                start = new Date(now.getFullYear(), now.getMonth(), 1);
                end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
                break;
            case 'last_month':
                start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
                end = new Date(now.getFullYear(), now.getMonth(), 0);
                break;
            case 'this_year':
                start = new Date(now.getFullYear(), 0, 1);
                end = new Date(now.getFullYear(), 11, 31);
                break;
        }
        setStartDate(start.toISOString().split('T')[0]);
        setEndDate(end.toISOString().split('T')[0]);
