import React, { useState, useMemo, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { Card } from '../components/common/Card';
import { BarChart } from '../components/common/BarChart';
import { PieChart } from '../components/common/PieChart';
import { LineChart } from '../components/common/LineChart';
import { ICONS } from '../constants';
import { TransactionType, ExpenseCategory } from '../types';
import { AttendanceReportTab } from '../components/reports/AttendanceReportTab';
import { TransactionHistoryReportTab } from '../components/reports/TransactionHistoryReportTab';
import { ReportDetailModal } from '../components/reports/ReportDetailModal';

const toLocalDateString = (date: Date): string => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
};

type ReportTab = 'dashboard' | 'attendance' | 'transactions';

export const ReportsScreen: React.FC = () => {
    const { state } = useData();
    const location = useLocation();
    const { transactions, expenses, income, classes, students } = state;

    const [activeTab, setActiveTab] = useState<ReportTab>('dashboard');

    // Date Filters
    const today = new Date();
    const startOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth(), 1));
    const endOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth() + 1, 0));

    const [startDate, setStartDate] = useState(startOfMonth);
    const [endDate, setEndDate] = useState(endOfMonth);
    const [classFilter, setClassFilter] = useState('all');

    const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; items: any[] }>({
        isOpen: false,
        title: '',
        items: []
    });

    useEffect(() => {
        if (location.state?.defaultReport) {
            setActiveTab(location.state.defaultReport);
        }
    }, [location.state]);

    // Derived Data for Dashboard
    const filteredStudentIds = useMemo(() => {
        if (classFilter === 'all') return null;
        const cls = classes.find(c => c.id === classFilter);
        return cls ? new Set(cls.studentIds) : new Set();
    }, [classes, classFilter]);

    const financialStats = useMemo(() => {
        // Revenue (Tuition + Other Income)
        const tuitionRevenue = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithin = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithin && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .reduce((sum, t) => sum + t.amount, 0);

        const otherIncome = classFilter === 'all' ? income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .reduce((sum, i) => sum + i.amount, 0) : 0;

        const totalRevenue = tuitionRevenue + otherIncome;

        // Expenses
        const totalExpenses = classFilter === 'all' ? expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .reduce((sum, e) => sum + e.amount, 0) : 0;

        // Profit
        const profit = totalRevenue - totalExpenses;

        return { totalRevenue, totalExpenses, profit, tuitionRevenue, otherIncome };
    }, [transactions, income, expenses, startDate, endDate, filteredStudentIds, classFilter]);

    // Charts Data
    const monthlyData = useMemo(() => {
        // Group by month for Line Chart
        const months = new Set<string>();
        // Helper to get YYYY-MM
        const getMonth = (dateStr: string) => dateStr.substring(0, 7);

        // Collect all months in range
        let curr = new Date(startDate);
        const end = new Date(endDate);
        while (curr <= end) {
            months.add(toLocalDateString(curr).substring(0, 7));
            curr.setMonth(curr.getMonth() + 1);
        }

        const sortedMonths = Array.from(months).sort();

        const revenueData = sortedMonths.map(m => {
            const mTuition = transactions
                .filter(t => t.date.startsWith(m) && (t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT) && t.amount > 0 && (!filteredStudentIds || filteredStudentIds.has(t.studentId)))
                .reduce((sum, t) => sum + t.amount, 0);

            const mIncome = classFilter === 'all' ? income
                .filter(i => i.date.startsWith(m))
                .reduce((sum, i) => sum + i.amount, 0) : 0;

            return mTuition + mIncome;
        });

        const expenseData = sortedMonths.map(m => {
            return classFilter === 'all' ? expenses
                .filter(e => e.date.startsWith(m))
                .reduce((sum, e) => sum + e.amount, 0) : 0;
        });

        return {
            labels: sortedMonths.map(m => `T${m.split('-')[1]}`),
            revenue: revenueData,
            expenses: expenseData
        };
    }, [startDate, endDate, transactions, income, expenses, filteredStudentIds, classFilter]);

    const expenseCategoryData = useMemo(() => {
        if (classFilter !== 'all') return [];
        const categoryTotals: Record<string, number> = {};
        expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .forEach(e => {
                categoryTotals[e.category] = (categoryTotals[e.category] || 0) + e.amount;
            });

        return Object.entries(categoryTotals).map(([key, value]) => ({
            label: key, // Should use a map for readable names
            value,
            color: '' // Color will be assigned in PieChart
        }));
    }, [expenses, startDate, endDate, classFilter]);

    const handleShowRevenueDetails = () => {
        const tuitionItems = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithin = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithin && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .map(t => {
                const studentName = students.find(s => s.id === t.studentId)?.name || 'Không rõ';
                return {
                    description: `[HP] ${studentName} - ${t.description}`,
                    date: t.date,
                    amount: t.amount,
                    type: 'credit' as const,
                    id: t.id
                };
            });

        const otherIncomeItems = classFilter === 'all' ? income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .map(i => ({
                description: `[Thu khác] ${i.description}`,
                date: i.date,
                amount: i.amount,
                type: 'credit' as const,
                id: i.id
            })) : [];

        // Sort descending by date (Newest first), then by ID descending (Newest entry first)
        const allItems = [...tuitionItems, ...otherIncomeItems].sort((a,b) => {
            const dateDiff = new Date(b.date).getTime() - new Date(a.date).getTime();
            if (dateDiff !== 0) return dateDiff;
            return b.id.localeCompare(a.id);
        });

        setDetailModal({ isOpen: true, title: `Chi tiết Doanh thu`, items: allItems });
    };

    const handleShowExpenseDetails = () => {
        if (classFilter !== 'all') return;
        const items = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .map(e => ({
                description: `[${e.category}] ${e.description}`,
                date: e.date,
                amount: e.amount,
                type: 'debit' as const,
                id: e.id
            }))
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

        setDetailModal({ isOpen: true, title: `Chi tiết Chi phí`, items });
    };

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Báo cáo & Thống kê</h1>

            {/* Filters */}
            <div className="card-base p-4 flex flex-col md:flex-row gap-4 items-end">
                <div className="w-full md:w-auto">
                    <label className="block text-sm font-medium mb-1">Từ ngày</label>
                    <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="form-input w-full" />
                </div>
                <div className="w-full md:w-auto">
                    <label className="block text-sm font-medium mb-1">Đến ngày</label>
                    <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="form-input w-full" />
                </div>
                <div className="w-full md:w-auto">
                    <label className="block text-sm font-medium mb-1">Lớp học</label>
                    <select value={classFilter} onChange={e => setClassFilter(e.target.value)} className="form-select w-full">
                        <option value="all">Tất cả</option>
                        {classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                </div>
            </div>

            {/* Tabs */}
            <div className="border-b border-gray-200 dark:border-gray-700">
                <nav className="-mb-px flex space-x-4 overflow-x-auto">
                    <button onClick={() => setActiveTab('dashboard')} className={`pb-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap ${activeTab === 'dashboard' ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300'}`}>
                        Tổng quan
                    </button>
                    <button onClick={() => setActiveTab('attendance')} className={`pb-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap ${activeTab === 'attendance' ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300'}`}>
                        Điểm danh
                    </button>
                    <button onClick={() => setActiveTab('transactions')} className={`pb-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap ${activeTab === 'transactions' ? 'border-primary text-primary' : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300'}`}>
                        Lịch sử Giao dịch
                    </button>
                </nav>
            </div>

            {activeTab === 'dashboard' && (
                <div className="space-y-6">
                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="card-base p-4 cursor-pointer hover:shadow-lg transition-shadow" onClick={handleShowRevenueDetails}>
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="text-sm font-medium text-gray-500">Tổng Doanh thu</p>
                                    <p className="text-2xl font-bold text-green-600 mt-1">{financialStats.totalRevenue.toLocaleString('vi-VN')} ₫</p>
                                </div>
                                <div className="p-2 bg-green-100 rounded-full text-green-600">{ICONS.finance}</div>
                            </div>
                            <div className="mt-2 text-xs text-gray-500">
                                <p>Học phí: {financialStats.tuitionRevenue.toLocaleString('vi-VN')} ₫</p>
                                {classFilter === 'all' && <p>Khác: {financialStats.otherIncome.toLocaleString('vi-VN')} ₫</p>}
                            </div>
                        </div>

                        <div className={`card-base p-4 ${classFilter !== 'all' ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer hover:shadow-lg transition-shadow'}`} onClick={handleShowExpenseDetails}>
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="text-sm font-medium text-gray-500">Tổng Chi phí</p>
                                    <p className="text-2xl font-bold text-red-600 mt-1">{financialStats.totalExpenses.toLocaleString('vi-VN')} ₫</p>
                                </div>
                                <div className="p-2 bg-red-100 rounded-full text-red-600">{ICONS.finance}</div>
                            </div>
                            {classFilter !== 'all' && <p className="text-xs text-red-500 mt-2">Chỉ xem được khi chọn "Tất cả lớp"</p>}
                        </div>

                        <div className="card-base p-4">
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="text-sm font-medium text-gray-500">Lợi nhuận</p>
                                    <p className={`text-2xl font-bold mt-1 ${financialStats.profit >= 0 ? 'text-blue-600' : 'text-red-600'}`}>{financialStats.profit.toLocaleString('vi-VN')} ₫</p>
                                </div>
                                <div className="p-2 bg-blue-100 rounded-full text-blue-600">{ICONS.dashboard}</div>
                            </div>
                        </div>
                    </div>

                    {/* Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <div className="card-base p-4">
                            <LineChart 
                                title="Biểu đồ Doanh thu & Chi phí theo tháng" 
                                data={monthlyData.labels.map((label, i) => ({
                                    label,
                                    values: [monthlyData.revenue[i], monthlyData.expenses[i]]
                                }))}
                                series={[
                                    { name: 'Doanh thu', color: '#10b981' }, // green
                                    { name: 'Chi phí', color: '#ef4444' }  // red
                                ]}
                            />
                        </div>
                        {classFilter === 'all' && (
                            <div className="card-base p-4">
                                <PieChart title="Cơ cấu Chi phí" data={expenseCategoryData} />
                            </div>
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'attendance' && (
                <AttendanceReportTab startDate={startDate} endDate={endDate} classFilter={classFilter} />
            )}

            {activeTab === 'transactions' && (
                <TransactionHistoryReportTab startDate={startDate} endDate={endDate} classFilter={classFilter} />
            )}

            <ReportDetailModal 
                isOpen={detailModal.isOpen} 
                onClose={() => setDetailModal(prev => ({ ...prev, isOpen: false }))} 
                title={detailModal.title} 
                items={detailModal.items} 
            />
        </div>
    );
};

