const removeAccents = (str: string) => {
  if (!str) return '';
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D");
};

const ClassSelector: React.FC<{
    allClasses: Class[];
    selectedClassIds: string[];
    onChange: (selectedIds: string[]) => void;
}> = ({ allClasses, selectedClassIds, onChange }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const filteredClasses = useMemo(() => {
        return allClasses.filter(cls =>
            cls.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [allClasses, searchTerm]);

    const handleToggle = (classId: string) => {
        const newSelectedIds = selectedClassIds.includes(classId)
            ? selectedClassIds.filter(id => id !== classId)
            : [...selectedClassIds, classId];
        onChange(newSelectedIds);
    };

    return (
        <div className="border rounded-md dark:border-gray-600 bg-white dark:bg-gray-800">
            <div className="p-2 border-b dark:border-gray-600">
                <input
                    type="text"
                    placeholder="Tìm kiếm lớp học..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="form-input w-full p-2"
                />
            </div>
            <div className="max-h-60 overflow-y-auto p-2">
                {filteredClasses.length > 0 ? (
                    filteredClasses.map(cls => (
                        <label key={cls.id} className="flex items-center p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={selectedClassIds.includes(cls.id)}
                                onChange={() => handleToggle(cls.id)}
                                className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                            />
                            <span className="ml-3 text-sm">{cls.name}</span>
                        </label>
                    ))
                ) : (
                    <p className="text-center text-sm text-gray-500 p-4">Không tìm thấy lớp học.</p>
                )}
            </div>
             <div className="p-2 border-t dark:border-gray-600 text-sm text-gray-500 dark:text-gray-400">
                Đã chọn: {selectedClassIds.length} lớp học
            </div>
        </div>
    );
};


const StudentForm: React.FC<{ 
    student?: Student; 
    onSubmit: (payload: { student: Student, classIds: string[] }) => void; 
    onCancel: () => void;
    allClasses: Class[];
}> = ({ student, onSubmit, onCancel, allClasses }) => {
    const [formData, setFormData] = useState<Partial<Student>>({
        id: '',
        name: '',
        email: '',
        phone: '',
        address: '',
        dob: '',
        parentName: '',
        status: PersonStatus.ACTIVE,
        createdAt: '',
        balance: 0,
        password: '',
        ...student,
    });
    const [selectedClassIds, setSelectedClassIds] = useState<string[]>([]);
    const [errors, setErrors] = useState<Partial<Record<keyof Student, string>>>({});
    const idInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        idInputRef.current?.focus();
        if (student) {
            const enrolledClassIds = allClasses
                .filter(c => c.studentIds.includes(student.id))
                .map(c => c.id);
            setSelectedClassIds(enrolledClassIds);
        }
    }, [student, allClasses]);

    const validate = () => {
        const newErrors: Partial<Record<keyof Student, string>> = {};
        if (!formData.id?.trim()) newErrors.id = "Mã học viên là bắt buộc.";
        if (!formData.name?.trim()) newErrors.name = "Họ tên là bắt buộc.";
        if (!formData.email?.trim()) {
            newErrors.email = "Email là bắt buộc.";
        } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = "Email không hợp lệ.";
        }
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };


    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (validate()) {
            const studentData = { ...formData };
            if (!studentData.password) {
                delete studentData.password;
            }
            onSubmit({ student: studentData as Student, classIds: selectedClassIds });
        }
    };

    const inputGroupClass = "grid grid-cols-1 md:grid-cols-2 gap-4";

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin cá nhân</legend>
                <div className={`${inputGroupClass} mt-2`}>
                    <div>
                        <label className="block text-sm font-medium">Mã Học viên <span className="text-red-500">*</span></label>
                        <input ref={idInputRef} type="text" name="id" value={formData.id} onChange={handleChange} className="form-input mt-1" />
                        {errors.id && <p className="text-red-500 text-xs mt-1">{errors.id}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Họ tên <span className="text-red-500">*</span></label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} className="form-input mt-1" />
                        {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Ngày sinh</label>
                        <input type="date" name="dob" value={formData.dob} onChange={handleChange} className="form-input mt-1" />
                    </div>
                     <div>
                        <label className="block text-sm font-medium">Trạng thái</label>
                        <select name="status" value={formData.status} onChange={handleChange} className="form-select mt-1">
                            <option value={PersonStatus.ACTIVE}>Hoạt động</option>
                            <option value={PersonStatus.INACTIVE}>Tạm nghỉ</option>
                        </select>
                    </div>
                </div>
            </fieldset>

             <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin liên lạc & Tài khoản</legend>
                 <div className={`${inputGroupClass} mt-2`}>
                    <div>
                        <label className="block text-sm font-medium">Email <span className="text-red-500">*</span></label>
                        <input type="email" name="email" value={formData.email} onChange={handleChange} className="form-input mt-1" />
                        {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Số điện thoại</label>
                        <input type="tel" name="phone" value={formData.phone} onChange={handleChange} className="form-input mt-1" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Tên phụ huynh</label>
                        <input type="text" name="parentName" value={formData.parentName} onChange={handleChange} className="form-input mt-1" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Mật khẩu</label>
                        <input type="password" name="password" value={formData.password || ''} onChange={handleChange} className="form-input mt-1" placeholder="Bỏ trống để dùng ngày sinh (ddmmyyyy)" />
                    </div>
                </div>
                 <div className="mt-4">
                    <label className="block text-sm font-medium">Địa chỉ</label>
                    <input type="text" name="address" value={formData.address} onChange={handleChange} className="form-input mt-1" />
                </div>
            </fieldset>

            <fieldset className="form-fieldset">
                <legend className="form-legend">Ghi danh Lớp học</legend>
                 <ClassSelector
                    allClasses={allClasses}
                    selectedClassIds={selectedClassIds}
                    onChange={setSelectedClassIds}
                />
            </fieldset>

            <div className="flex justify-end space-x-4 pt-4 border-t dark:border-gray-700">
                <Button type="button" variant="secondary" onClick={onCancel}>Hủy</Button>
                <Button type="submit">{student ? 'Lưu thay đổi' : 'Thêm học viên'}</Button>
            </div>
        </form>
    );
};


export const StudentsScreen: React.FC = () => {
    const { state, addStudent, updateStudent, deleteStudent } = useData();
    const { role } = useAuth();
    const { toast } = useToast();
    const location = useLocation<{ editStudentId?: string; returnTo?: string }>();
    const history = useHistory();
    const [isModalOpen, setModalOpen] = useState(false);
    const [editingStudent, setEditingStudent] = useState<Student | undefined>(undefined);
    const [confirmModalState, setConfirmModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [resetPasswordModalState, setResetPasswordModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [paymentModalState, setPaymentModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [searchQuery, setSearchQuery] = useState('');
    const [classFilter, setClassFilter] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const [sortConfig, setSortConfig] = useState<SortConfig<Student> | null>({ key: 'name', direction: 'ascending' });
    const ITEMS_PER_PAGE = 10;

    const canManage = role === UserRole.ADMIN || role === UserRole.MANAGER;

    const handleSort = (key: keyof Student) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setSortConfig({ key, direction });
    };

    const handleOpenModal = (student?: Student) => {
        setEditingStudent(student);
        setModalOpen(true);
    };

    useEffect(() => {
        const { editStudentId } = location.state || {};
        if (editStudentId && !isModalOpen) {
            const studentToEdit = state.students.find(s => s.id === editStudentId);
            if (studentToEdit) {
                handleOpenModal(studentToEdit);
            }
        }
    }, [location.state, state.students, isModalOpen]);

    const filteredStudents = useMemo(() => {
        let studentsToFilter = state.students;

        if (classFilter !== 'all') {
            const selectedClass = state.classes.find(c => c.id === classFilter);
            if (selectedClass) {
                const studentIdsInClass = new Set(selectedClass.studentIds);
                studentsToFilter = studentsToFilter.filter(s => studentIdsInClass.has(s.id));
            }
        }

        if (!searchQuery) return studentsToFilter;

        const normalizedQuery = removeAccents(searchQuery.toLowerCase());
        return studentsToFilter.filter(s => {
            const normalizedName = removeAccents(s.name.toLowerCase());
            const phoneMatch = s.phone.includes(searchQuery);
            const nameMatch = normalizedName.includes(normalizedQuery);
            return phoneMatch || nameMatch;
        });
    }, [state.students, state.classes, searchQuery, classFilter]);

    const sortedStudents = useMemo(() => {
        let sortableItems = [...filteredStudents];

        if (searchQuery) {
            const normalizedQuery = removeAccents(searchQuery.toLowerCase());

            const getScore = (student: Student) => {
                // Phone match is highest priority
                if (student.phone.includes(searchQuery)) {
                    return 3;
                }

                const normalizedName = removeAccents(student.name.toLowerCase());
                const nameParts = normalizedName.split(' ');
                const lastName = nameParts[nameParts.length - 1];

                // Last name match is second priority
                if (lastName.startsWith(normalizedQuery)) {
                    return 2;
                }

                // Any other name match is lowest priority
                if (normalizedName.includes(normalizedQuery)) {
                    return 1;
                }

                return 0;
            };

            sortableItems.sort((a, b) => {
                const scoreA = getScore(a);
                const scoreB = getScore(b);

                if (scoreA !== scoreB) {
                    return scoreB - scoreA; // Higher score comes first
                }

                // If scores are equal, sort by name alphabetically
                return a.name.localeCompare(b.name, 'vi');
            });

        } else if (sortConfig !== null) {
            // Original sorting logic when not searching
            const getLastName = (fullName: string) => {
                if (!fullName) return '';
                const parts = fullName.trim().split(/\s+/);
                return parts[parts.length - 1];
            };

            sortableItems.sort((a, b) => {
                if (sortConfig.key === 'name') {
                    const lastNameA = getLastName(a.name);
                    const lastNameB = getLastName(b.name);

                    const lastNameComparison = lastNameA.localeCompare(lastNameB, 'vi');

                    if (lastNameComparison !== 0) {
                        return sortConfig.direction === 'ascending' ? lastNameComparison : -lastNameComparison;
                    }

                    // If last names are the same, sort by full name for stability
                    const fullNameComparison = a.name.localeCompare(b.name, 'vi');
                    return sortConfig.direction === 'ascending' ? fullNameComparison : -fullNameComparison;
                }

                // Fallback for other columns
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];

                if (aValue == null || bValue == null) return 0;

                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [filteredStudents, sortConfig, searchQuery]);

    const totalPages = Math.ceil(sortedStudents.length / ITEMS_PER_PAGE);
    const paginatedStudents = sortedStudents.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, classFilter, sortConfig]);


    const columns = [
        { header: 'Mã HV', accessor: 'id' as keyof Student, sortable: true },
        { 
            header: 'Họ tên', 
            accessor: (item: Student) => (
                <Link to={`/student/${item.id}`} className="text-primary dark:text-indigo-400 hover:underline font-semibold">
                    {item.name}
                </Link>
            ),
            sortable: true,
            sortKey: 'name' as keyof Student,
        },
        { header: 'Số điện thoại', accessor: 'phone' as keyof Student },
        { 
            header: 'Số dư', 
            accessor: (item: Student) => {
                const balanceText = (
                    <span className={`font-semibold ${item.balance < 0 ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                        {item.balance.toLocaleString('vi-VN')} ₫
                    </span>
                );

                if (role === UserRole.VIEWER || item.balance >= 0) {
                    return balanceText;
                }

                return (
                    <button 
                        onClick={() => setPaymentModalState({ isOpen: true, student: item })}
                        className="font-semibold text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-300 hover:underline"
                        title="Ghi nhận thanh toán"
                    >
                        {item.balance.toLocaleString('vi-VN')} ₫
                    </button>
                );
            },
            sortable: true,
            sortKey: 'balance' as keyof Student
        },
        { header: 'Trạng thái', accessor: (item: Student) => (
            <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                item.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
            }`}>
                {item.status === PersonStatus.ACTIVE ? 'Hoạt động' : 'Tạm nghỉ'}
            </span>
        ), sortable: true, sortKey: 'status' as keyof Student },
    ];

    const handleCloseModal = () => {
        setEditingStudent(undefined);
        setModalOpen(false);
        const { returnTo } = location.state || {};
        if (returnTo) {
            history.replace(returnTo, {});
        }
    };

    const handleSubmit = async (payload: { student: Student; classIds: string[] }) => {
        const { returnTo } = location.state || {};
        try {
            if (editingStudent) {
                await updateStudent({ 
                    originalId: editingStudent.id, 
                    updatedStudent: payload.student,
                    classIds: payload.classIds 
                });
                toast.success(`Đã cập nhật thông tin học viên ${payload.student.name}`);
                setModalOpen(false);
                setEditingStudent(undefined);
                if (returnTo) {
                    history.replace(`/student/${payload.student.id}`, {});
                }
            } else {
                await addStudent(payload);
                toast.success(`Đã thêm học viên mới ${payload.student.name}`);
                handleCloseModal();
            }
        } catch (error: any) {
            toast.error(error.message || 'Đã xảy ra lỗi. Vui lòng thử lại.');
        }
    };

    const handleDeleteClick = (student: Student) => {
        setConfirmModalState({ isOpen: true, student: student });
    };

    const handleConfirmDelete = async () => {
        if (confirmModalState.student) {
            try {
                await deleteStudent(confirmModalState.student.id);
                toast.success(`Đã xoá học viên ${confirmModalState.student.name}`);
            } catch (error) {
                toast.error('Đã xảy ra lỗi khi xóa. Vui lòng thử lại.');
            }
        }
    };


    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="text-2xl font-bold">Quản lý Học viên</h1>
                {canManage && (
                    <Button onClick={() => handleOpenModal()}>
                        {ICONS.plus} Thêm học viên
                    </Button>
                )}
            </div>
            <div className="card-base p-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input 
                        type="text" 
                        placeholder="Tìm kiếm học viên (tên, SĐT)..." 
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="form-input"
                    />
                    <select
                        value={classFilter}
                        onChange={e => setClassFilter(e.target.value)}
                        className="form-select"
                    >
                        <option value="all">Lọc theo lớp - Tất cả</option>
                        {state.classes.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Desktop Table View */}
            <div className="hidden md:block">
                 <Table<Student>
                    columns={columns}
                    data={paginatedStudents}
                    sortConfig={sortConfig}
                    onSort={handleSort}
                    actions={canManage ? (student) => (
                        <>
                            <button onClick={() => setResetPasswordModalState({ isOpen: true, student: student })} className="text-gray-500 hover:text-gray-800" title="Đặt lại mật khẩu">{React.cloneElement(ICONS.key as React.ReactElement<{ width?: number | string; height?: number | string }>, {width: 20, height: 20})}</button>
                            <button onClick={() => handleOpenModal(student)} className="text-indigo-600 hover:text-indigo-900">{ICONS.edit}</button>
                            <button onClick={() => handleDeleteClick(student)} className="text-red-600 hover:text-red-900">{ICONS.delete}</button>
                        </>
                    ) : undefined}
                />
            </div>

            {/* Mobile Card View */}
            <div className="md:hidden space-y-4">
                {paginatedStudents.map(student => (
                    <div key={student.id} className="card-base p-4">
                        <div className="flex justify-between items-start gap-3">
                            <div className="flex-1">
                                <Link to={`/student/${student.id}`} className="block group">
                                    <h3 className="font-bold text-lg text-primary group-hover:underline">{student.name}</h3>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 font-mono">{student.id}</p>
                                </Link>
                            </div>
                            <span className={`px-2 py-0.5 text-[10px] uppercase tracking-wider font-bold rounded-full shadow-sm ${student.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900/50 dark:text-red-300'} whitespace-nowrap mt-1`}>
                                {student.status === PersonStatus.ACTIVE ? 'Hoạt động' : 'Tạm nghỉ'}
                            </span>
                        </div>

                        <div className="mt-4 grid grid-cols-2 gap-4 text-sm border-t border-gray-100 dark:border-gray-700 pt-3">
                            <div>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Số điện thoại</p>
                                <p className="font-medium text-gray-800 dark:text-gray-200">{student.phone || 'Chưa có'}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Số dư</p>
                                <p className={`font-bold text-base ${student.balance < 0 ? 'text-red-500' : 'text-green-600'}`}>
                                    {student.balance.toLocaleString('vi-VN')} ₫
                                </p>
                            </div>
                        </div>

                        {canManage && (
                            <div className="mt-3 border-t border-gray-100 dark:border-gray-700 pt-3 flex justify-end items-center space-x-1">
                                {student.balance < 0 && (
                                    <button onClick={() => setPaymentModalState({ isOpen: true, student: student })} className="p-2 rounded-full text-green-600 hover:bg-green-100 dark:hover:bg-green-900/50" title="Ghi nhận thanh toán">
                                        {React.cloneElement(ICONS.finance, {width: 20, height: 20})}
                                    </button>
                                )}
                                <button onClick={() => setResetPasswordModalState({ isOpen: true, student: student })} className="p-2 rounded-full text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700" title="Đặt lại mật khẩu">
                                    {React.cloneElement(ICONS.key, {width: 20, height: 20})}
                                </button>
                                <button onClick={() => handleOpenModal(student)} className="p-2 rounded-full text-indigo-600 hover:bg-indigo-100 dark:hover:bg-indigo-900/50" title="Sửa">
                                    {ICONS.edit}
                                </button>
                                <button onClick={() => handleDeleteClick(student)} className="p-2 rounded-full text-red-600 hover:bg-red-100 dark:hover:bg-red-900/50" title="Xóa">
                                    {ICONS.delete}
                                </button>
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {paginatedStudents.length > 0 && (
                 <Pagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setCurrentPage}
                    totalItems={sortedStudents.length}
                    itemsPerPage={ITEMS_PER_PAGE}
                />
            )}

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={editingStudent ? 'Chỉnh sửa Học viên' : 'Thêm Học viên mới'}>
                <StudentForm 
                    student={editingStudent} 
                    onSubmit={handleSubmit} 
                    onCancel={handleCloseModal}
                    allClasses={state.classes}
                />
            </Modal>
             <ConfirmationModal
                isOpen={confirmModalState.isOpen}
                onClose={() => setConfirmModalState({ isOpen: false, student: null })}
                onConfirm={handleConfirmDelete}
                title="Xác nhận Xóa Học viên"
                message={
                    <p>
                        Bạn có chắc chắn muốn xoá học viên <strong>{confirmModalState.student?.name}</strong>?
                        <br /><br />
                        <span className="font-bold text-red-500">CẢNH BÁO:</span> Toàn bộ dữ liệu học phí, điểm danh và báo cáo của học viên này cũng sẽ bị XOÁ VĨNH VIỄN.
                    </p>
                }
            />
            <ResetPasswordModal
                isOpen={resetPasswordModalState.isOpen}
                onClose={() => setResetPasswordModalState({ isOpen: false, student: null })}
                user={resetPasswordModalState.student}
                role={UserRole.PARENT}
            />
             <PaymentModal
                isOpen={paymentModalState.isOpen}
                onClose={() => setPaymentModalState({ isOpen: false, student: null })}
                student={paymentModalState.student}
            />
        </div>
    );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Link, useLocation, useHistory } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useToast } from '../hooks/useToast';
import { useAuth } from '../hooks/useAuth';
import { Table, SortConfig } from '../components/common/Table';
import { Button } from '../components/common/Button';
import { Modal } from '../components/common/Modal';
import { ICONS } from '../constants';
import { PersonStatus, Teacher, UserRole, SalaryType } from '../types';
import { CurrencyInput } from '../components/common/CurrencyInput';
import { ConfirmationModal } from '../components/common/ConfirmationModal';
import { Pagination } from '../components/common/Pagination';
import { ListItemCard } from '../components/common/ListItemCard';
import { ResetPasswordModal } from '../components/auth/ChangePasswordModal';

const TeacherForm: React.FC<{ teacher?: Teacher; onSubmit: (teacher: Teacher) => void; onCancel: () => void; }> = ({ teacher, onSubmit, onCancel }) => {
    const [formData, setFormData] = useState<Partial<Teacher>>({
        id: '',
        name: '',
        email: '',
        phone: '',
        address: '',
        qualification: '',
        subject: '',
        status: PersonStatus.ACTIVE,
        salaryType: SalaryType.MONTHLY,
        rate: 0,
        dob: '',
        role: UserRole.TEACHER,
        createdAt: '',
        password: '',
        ...teacher,
    });
    const [errors, setErrors] = useState<Partial<Record<keyof Teacher, string>>>({});
    const idInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        idInputRef.current?.focus();
    }, []);

    const validate = () => {
        const newErrors: Partial<Record<keyof Teacher, string>> = {};
        if (!formData.id?.trim()) newErrors.id = "Mã giáo viên là bắt buộc.";
        if (!formData.name?.trim()) newErrors.name = "Họ tên là bắt buộc.";
        if (!formData.subject?.trim()) newErrors.subject = "Chuyên môn là bắt buộc.";
        if (!formData.dob) newErrors.dob = "Ngày sinh là bắt buộc.";
        if (formData.email && !/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = "Email không hợp lệ.";
        }
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };


    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleRateChange = (amount: number) => {
        setFormData(prev => ({ ...prev, rate: amount }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if(!validate()) return;

        const dataToSubmit: Partial<Teacher> = { ...formData };
        if (!dataToSubmit.password) {
            delete dataToSubmit.password;
        }
        onSubmit(dataToSubmit as Teacher);
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin Tài khoản</legend>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2">
                    <div>
                        <label className="block text-sm font-medium">Mã Giáo viên <span className="text-red-500">*</span></label>
                        <input ref={idInputRef} type="text" name="id" value={formData.id} onChange={handleChange} className="form-input mt-1" />
                        {errors.id && <p className="text-red-500 text-xs mt-1">{errors.id}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Họ tên <span className="text-red-500">*</span></label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} className="form-input mt-1" />
                        {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                    </div>
                     <div>
                        <label className="block text-sm font-medium">Ngày sinh <span className="text-red-500">*</span></label>
                        <input type="date" name="dob" value={formData.dob} onChange={handleChange} className="form-input mt-1" />
                        {errors.dob && <p className="text-red-500 text-xs mt-1">{errors.dob}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Email</label>
                        <input type="email" name="email" value={formData.email} onChange={handleChange} className="form-input mt-1" />
                        {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Mật khẩu</label>
                        <input type="password" name="password" value={formData.password || ''} onChange={handleChange} className="form-input mt-1" placeholder="Bỏ trống để dùng ngày sinh (ddmmyyyy)" />
                    </div>
                </div>
            </fieldset>

            <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin Chuyên môn & Liên lạc</legend>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2">
                    <div>
                        <label className="block text-sm font-medium">Chuyên môn <span className="text-red-500">*</span></label>
                        <input type="text" name="subject" value={formData.subject} onChange={handleChange} className="form-input mt-1" />
                        {errors.subject && <p className="text-red-500 text-xs mt-1">{errors.subject}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Bằng cấp</label>
                        <input type="text" name="qualification" value={formData.qualification} onChange={handleChange} className="form-input mt-1" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Số điện thoại</label>
                        <input type="tel" name="phone" value={formData.phone} onChange={handleChange} className="form-input mt-1" />
                    </div>
                </div>
                 <div className="mt-4">
                    <label className="block text-sm font-medium">Địa chỉ</label>
                    <input type="text" name="address" value={formData.address} onChange={handleChange} className="form-input mt-1" />
                </div>
            </fieldset>

            <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin Lương & Trạng thái</legend>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2">
                    <div>
                        <label className="block text-sm font-medium">Hình thức trả lương</label>
                        <select name="salaryType" value={formData.salaryType} onChange={handleChange} className="form-select mt-1">
                            <option value={SalaryType.MONTHLY}>Lương cứng (tháng)</option>
                            <option value={SalaryType.PER_SESSION}>Lương theo buổi dạy</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Mức lương (VND)</label>
                        <CurrencyInput value={formData.rate || 0} onChange={handleRateChange} className="form-input mt-1" />
                    </div>
                     <div>
                        <label className="block text-sm font-medium">Trạng thái</label>
                        <select name="status" value={formData.status} onChange={handleChange} className="form-select mt-1">
                            <option value={PersonStatus.ACTIVE}>Đang dạy</option>
                            <option value={PersonStatus.INACTIVE}>Đã nghỉ</option>
                        </select>
                    </div>
                </div>
            </fieldset>

            <div className="flex justify-end space-x-4 pt-4 border-t dark:border-gray-700">
                <Button type="button" variant="secondary" onClick={onCancel}>Hủy</Button>
                <Button type="submit">{teacher ? 'Lưu thay đổi' : 'Thêm giáo viên'}</Button>
            </div>
        </form>
    );
};

export const TeachersScreen: React.FC = () => {
    const { state, addTeacher, updateTeacher, deleteTeacher } = useData();
    const { role } = useAuth();
    const { toast } = useToast();
    const location = useLocation<{ editTeacherId?: string; returnTo?: string }>();
    const history = useHistory();
    const [isModalOpen, setModalOpen] = useState(false);
    const [editingTeacher, setEditingTeacher] = useState<Teacher | undefined>(undefined);
    const [confirmModalState, setConfirmModalState] = useState<{ isOpen: boolean; teacher: Teacher | null }>({ isOpen: false, teacher: null });
    const [resetPasswordModalState, setResetPasswordModalState] = useState<{ isOpen: boolean; teacher: Teacher | null }>({ isOpen: false, teacher: null });
    const [searchQuery, setSearchQuery] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [sortConfig, setSortConfig] = useState<SortConfig<Teacher> | null>({ key: 'createdAt', direction: 'descending' });
    const ITEMS_PER_PAGE = 10;

    const canManage = role === UserRole.ADMIN || role === UserRole.MANAGER;

    const handleSort = (key: keyof Teacher) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setSortConfig({ key, direction });
    };

    const filteredTeachers = useMemo(() => {
        if (!searchQuery) return state.teachers;
        const lowercasedQuery = searchQuery.toLowerCase();
        return state.teachers.filter(t =>
            t.id.toLowerCase().includes(lowercasedQuery) ||
            t.name.toLowerCase().includes(lowercasedQuery) ||
            (t.email && t.email.toLowerCase().includes(lowercasedQuery)) ||
            t.subject.toLowerCase().includes(lowercasedQuery)
        );
    }, [state.teachers, searchQuery]);

    const sortedTeachers = useMemo(() => {
        let sortableItems = [...filteredTeachers];
        if (sortConfig !== null) {
            sortableItems.sort((a, b) => {
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];
                if (aValue == null || bValue == null) return 0;
                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [filteredTeachers, sortConfig]);

    const totalPages = Math.ceil(sortedTeachers.length / ITEMS_PER_PAGE);
    const paginatedTeachers = sortedTeachers.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, sortConfig]);


    const columns = [
        { header: 'Mã GV', accessor: 'id' as keyof Teacher, sortable: true },
        { 
            header: 'Họ tên', 
            accessor: (item: Teacher) => (
                <Link to={`/teacher/${item.id}`} className="text-primary dark:text-indigo-400 hover:underline font-semibold">
                    {item.name}
                </Link>
            ),
            sortable: true,
            sortKey: 'name' as keyof Teacher,
        },
        { header: 'Chuyên môn', accessor: 'subject' as keyof Teacher, sortable: true },
        { header: 'Email', accessor: 'email' as keyof Teacher, sortable: true },
        { header: 'Số điện thoại', accessor: 'phone' as keyof Teacher },
        { header: 'Trạng thái', accessor: (item: Teacher) => (
            <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                item.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
            }`}>
                {item.status === PersonStatus.ACTIVE ? 'Đang dạy' : 'Đã nghỉ'}
            </span>
        ), sortable: true, sortKey: 'status' as keyof Teacher},
    ];

    const handleOpenModal = (teacher?: Teacher) => {
        setEditingTeacher(teacher);
        setModalOpen(true);
    };

    const handleCloseModal = () => {
        setEditingTeacher(undefined);
        setModalOpen(false);
        const { returnTo } = location.state || {};
        if (returnTo) {
            history.replace(returnTo, {});
        }
    };

    const handleSubmit = async (data: Teacher) => {
        const { returnTo } = location.state || {};
        try {
            if (editingTeacher) {
                await updateTeacher({ originalId: editingTeacher.id, updatedTeacher: data });
                toast.success(`Đã cập nhật thông tin giáo viên ${data.name}`);
                setModalOpen(false);
                setEditingTeacher(undefined);
                if (returnTo) {
                    history.replace(`/teacher/${data.id}`, {});
                }
            } else {
                await addTeacher(data);
                toast.success(`Đã thêm giáo viên mới ${data.name}`);
                handleCloseModal();
            }
        } catch (error: any) {
            toast.error(error.message || 'Đã xảy ra lỗi. Vui lòng thử lại.');
        }
    };

    const handleDeleteClick = (teacher: Teacher) => {
        const teacherHasClasses = state.classes.some(c => (c.teacherIds || []).includes(teacher.id));
        if (teacherHasClasses) {
            toast.error(`Không thể xóa giáo viên ${teacher.name} vì họ vẫn đang phụ trách lớp học.`);
            return;
        }
        setConfirmModalState({ isOpen: true, teacher });
    };

    const handleConfirmDelete = async () => {
        if (confirmModalState.teacher) {
            try {
                await deleteTeacher(confirmModalState.teacher.id);
                toast.success(`Đã xóa giáo viên ${confirmModalState.teacher.name}`);
            } catch (error: any) {
                toast.error(error.message || 'Đã xảy ra lỗi khi xóa.');
            }
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="text-2xl font-bold">Quản lý Giáo viên</h1>
                {canManage && (
                    <Button onClick={() => handleOpenModal()}>
                        {ICONS.plus} Thêm giáo viên
                    </Button>
                )}
            </div>
             <div className="mb-4">
                <input 
                    type="text" 
                    placeholder="Tìm kiếm giáo viên (mã, tên, email, chuyên môn)..." 
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    className="form-input w-full"
                />
            </div>

            {/* Desktop Table View */}
            <div className="hidden md:block">
                <Table<Teacher>
                    columns={columns}
                    data={paginatedTeachers}
                    sortConfig={sortConfig}
                    onSort={handleSort}
                    actions={canManage ? (teacher) => (
                        <>
                            <button onClick={() => setResetPasswordModalState({ isOpen: true, teacher: teacher })} className="text-gray-500 hover:text-gray-800" title="Đặt lại mật khẩu">{React.cloneElement(ICONS.key as React.ReactElement<{ width?: number | string; height?: number | string }>, {width: 20, height: 20})}</button>
                            <button onClick={() => handleOpenModal(teacher)} className="text-indigo-600 hover:text-indigo-900">{ICONS.edit}</button>
                            <button onClick={() => handleDeleteClick(teacher)} className="text-red-600 hover:text-red-900">{ICONS.delete}</button>
                        </>
                    ) : undefined}
                />
            </div>

            {/* Mobile Card View */}
            <div className="md:hidden space-y-4">
                {paginatedTeachers.map(teacher => (
                    <ListItemCard
                        key={teacher.id}
                        title={
                            <Link to={`/teacher/${teacher.id}`} className="font-semibold text-primary hover:underline">
                                {teacher.name}
                            </Link>
                        }
                        details={[
                            { label: "Mã GV", value: teacher.id },
                            { label: "Môn", value: teacher.subject },
                        ]}
                         status={{
                            text: teacher.status === PersonStatus.ACTIVE ? 'Đang dạy' : 'Đã nghỉ',
                            colorClasses: teacher.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                        }}
                        actions={canManage ? (
                           <div className="flex items-center space-x-2">
                                <button onClick={() => setResetPasswordModalState({ isOpen: true, teacher: teacher })} className="p-2 rounded-full text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700" title="Đặt lại mật khẩu">{React.cloneElement(ICONS.key as React.ReactElement<{ width?: number | string; height?: number | string }>, {width: 20, height: 20})}</button>
                                <button onClick={() => handleOpenModal(teacher)} className="p-2 rounded-full text-indigo-600 hover:bg-indigo-100 dark:hover:bg-indigo-900/50" title="Sửa">{ICONS.edit}</button>
                                <button onClick={() => handleDeleteClick(teacher)} className="p-2 rounded-full text-red-600 hover:bg-red-100 dark:hover:bg-red-900/50" title="Xóa">{ICONS.delete}</button>
                           </div>
                        ) : undefined}
                    />
                ))}
            </div>

            {paginatedTeachers.length > 0 && (
                 <Pagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setCurrentPage}
                    totalItems={sortedTeachers.length}
                    itemsPerPage={ITEMS_PER_PAGE}
                />
            )}

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={editingTeacher ? 'Chỉnh sửa Giáo viên' : 'Thêm Giáo viên mới'}>
                <TeacherForm teacher={editingTeacher} onSubmit={handleSubmit} onCancel={handleCloseModal} />
            </Modal>
            <ConfirmationModal
                isOpen={confirmModalState.isOpen}
                onClose={() => setConfirmModalState({ isOpen: false, teacher: null })}
                onConfirm={handleConfirmDelete}
                title="Xác nhận Xóa Giáo viên"
                message={<p>Bạn có chắc chắn muốn xóa giáo viên <strong>{confirmModalState.teacher?.name}</strong>?</p>}
            />
            <ResetPasswordModal
                isOpen={resetPasswordModalState.isOpen}
                onClose={() => setResetPasswordModalState({ isOpen: false, teacher: null })}
                user={resetPasswordModalState.teacher}
                role={UserRole.TEACHER}
            />
        </div>
    );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Link, useLocation, useHistory } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useAuth } from '../hooks/useAuth';
import { useToast } from '../hooks/useToast';
import { Button } from '../components/common/Button';
import { Modal } from '../components/common/Modal';
import { ICONS } from '../constants';
import { Class, UserRole, FeeType, ClassSchedule, Teacher, Student, PersonStatus } from '../types';
import { CurrencyInput } from '../components/common/CurrencyInput';
import { ConfirmationModal } from '../components/common/ConfirmationModal';
import { ListItemCard } from '../components/common/ListItemCard';

// New Component: TeacherSelector
const TeacherSelector: React.FC<{
    teachers: Teacher[];
    selectedTeacherIds: string[];
    onChange: (selectedIds: string[]) => void;
}> = ({ teachers, selectedTeacherIds, onChange }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const filteredTeachers = useMemo(() => {
        return teachers.filter(teacher =>
            teacher.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [teachers, searchTerm]);

    const handleToggle = (teacherId: string) => {
        const newSelectedIds = selectedTeacherIds.includes(teacherId)
            ? selectedTeacherIds.filter(id => id !== teacherId)
            : [...selectedTeacherIds, teacherId];
        onChange(newSelectedIds);
    };

    return (
        <div className="border rounded-md dark:border-gray-600">
            <div className="p-2 border-b dark:border-gray-600">
                <input
                    type="text"
                    placeholder="Tìm kiếm giáo viên..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="form-input w-full p-2"
                />
            </div>
            <div className="max-h-60 overflow-y-auto p-2">
                {filteredTeachers.length > 0 ? (
                    filteredTeachers.map(teacher => (
                        <label key={teacher.id} className="flex items-center p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={selectedTeacherIds.includes(teacher.id)}
                                onChange={() => handleToggle(teacher.id)}
                                className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                            />
                            <span className="ml-3 text-sm">{teacher.name}</span>
                        </label>
                    ))
                ) : (
                    <p className="text-center text-sm text-gray-500 p-4">Không tìm thấy giáo viên.</p>
                )}
            </div>
             <div className="p-2 border-t dark:border-gray-600 text-sm text-gray-500 dark:text-gray-400">
                Đã chọn: {selectedTeacherIds.length} giáo viên
            </div>
        </div>
    );
};


// New Component: Advanced Student Selector
function StudentSelector({
  students,
  selectedStudentIds,
  onChange,
}: {
  students: Student[];
  selectedStudentIds: string[];
  onChange: (selectedIds: string[]) => void;
}) {
    const [searchTerm, setSearchTerm] = useState('');

    const filteredStudents = useMemo(() => {
        return students.filter(student =>
            student.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [students, searchTerm]);

    const handleToggle = (studentId: string) => {
        const newSelectedIds = selectedStudentIds.includes(studentId)
            ? selectedStudentIds.filter(id => id !== studentId)
            : [...selectedStudentIds, studentId];
        onChange(newSelectedIds);
    };

    return (
        <div className="border rounded-md dark:border-gray-600">
            <div className="p-2 border-b dark:border-gray-600">
                <input
                    type="text"
                    placeholder="Tìm kiếm học viên..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="form-input w-full p-2"
                />
            </div>
            <div className="max-h-60 overflow-y-auto p-2">
                {filteredStudents.length > 0 ? (
                    filteredStudents.map(student => (
                        <label key={student.id} className="flex items-center p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer">
                            <input
                                type="checkbox"
