            {classAnnouncements.length === 0 ? (
                <p className="text-gray-500 text-center py-4">Chưa có thông báo nào cho lớp này.</p>
            ) : (
                <div className="space-y-4">
                    {classAnnouncements.map(ann => (
                        <div key={ann.id} className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">
                            <h3 className="font-semibold text-lg">{ann.title}</h3>
                            <p className="text-xs text-gray-500 dark:text-gray-400">
                                Đăng ngày {ann.createdAt} bởi {ann.createdBy}
                            </p>
                            <p className="mt-2 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{ann.content}</p>
                        </div>
                    ))}
                </div>
            )}
             <Modal isOpen={isModalOpen} onClose={() => setModalOpen(false)} title="Tạo Thông báo Lớp học">
                <ClassAnnouncementForm
                    onSubmit={handleAddAnnouncement}
                    onCancel={() => setModalOpen(false)}
                />
            </Modal>
        </>
    );
}

export const ClassDetailScreen: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const location = useLocation<{ defaultTab?: ClassDetailTab }>();
    const history = useHistory();
    const { state, addProgressReport, deleteClass } = useData();
    const { user, role } = useAuth();
    const { toast } = useToast();
    const { classes, students, teachers, progressReports, attendance } = state;
    const [isReportModalOpen, setReportModalOpen] = useState(false);
    const [activeTab, setActiveTab] = useState<ClassDetailTab>('students');
    const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);

    const canManage = role === UserRole.ADMIN || role === UserRole.MANAGER;

    useEffect(() => {
        if (location.state?.defaultTab) {
            setActiveTab(location.state.defaultTab);
        }
    }, [location.state]);

    const cls = classes.find(c => c.id === id);

    if (!cls) return <div>Lớp học không tồn tại.</div>;
    if (!user || !user.id) return <div>Lỗi xác thực người dùng.</div>;

    const teacherNames = useMemo(() => {
        return (cls.teacherIds || [])
            .map(id => teachers.find(t => t.id === id)?.name)
            .filter(Boolean)
            .join(', ');
    }, [cls.teacherIds, teachers]);

    const classStudents = useMemo(() => students.filter(s => (cls.studentIds || []).includes(s.id) && s.status === PersonStatus.ACTIVE), [students, cls.studentIds]);
    const classProgressReports = useMemo(() => progressReports.filter(pr => pr.classId === id), [progressReports, id]);
    const classAttendance = useMemo(() => attendance.filter(a => a.classId === id), [attendance, id]);

    const [studentSortConfig, setStudentSortConfig] = useState<SortConfig<Student> | null>({ key: 'name', direction: 'ascending' });
    const handleStudentSort = (key: keyof Student) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (studentSortConfig && studentSortConfig.key === key && studentSortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setStudentSortConfig({ key, direction });
    };
    const sortedClassStudents = useMemo(() => {
        let sortableItems = [...classStudents];
        if (studentSortConfig) {
            const getLastName = (fullName: string) => {
                if (!fullName) return '';
                const parts = fullName.trim().split(/\s+/);
                return parts[parts.length - 1];
            };

            sortableItems.sort((a, b) => {
                if (studentSortConfig.key === 'name') {
                    const lastNameA = getLastName(a.name);
                    const lastNameB = getLastName(b.name);

                    const lastNameComparison = lastNameA.localeCompare(lastNameB, 'vi');

                    if (lastNameComparison !== 0) {
                        return studentSortConfig.direction === 'ascending' ? lastNameComparison : -lastNameComparison;
                    }

                    // If last names are the same, sort by full name for stability
                    const fullNameComparison = a.name.localeCompare(b.name, 'vi');
                    return studentSortConfig.direction === 'ascending' ? fullNameComparison : -fullNameComparison;
                }

                // Fallback for other columns
                const aValue = a[studentSortConfig.key];
                const bValue = b[studentSortConfig.key];

                if (aValue == null || bValue == null) return 0;

                if (aValue < bValue) return studentSortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return studentSortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [classStudents, studentSortConfig]);

    const [reportSortConfig, setReportSortConfig] = useState<SortConfig<ProgressReport> | null>({ key: 'date', direction: 'descending' });
    const handleReportSort = (key: keyof ProgressReport) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (reportSortConfig && reportSortConfig.key === key && reportSortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setReportSortConfig({ key, direction });
    };
    const sortedClassProgressReports = useMemo(() => {
        let sortableItems = [...classProgressReports];
        if (reportSortConfig) {
            sortableItems.sort((a, b) => {
                const aValue = a[reportSortConfig.key];
                const bValue = b[reportSortConfig.key];
                if (aValue < bValue) return reportSortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return reportSortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [classProgressReports, reportSortConfig]);

    const getStudentName = (studentId: string) => students.find(s => s.id === studentId)?.name || 'N/A';

    const studentColumns = [
        { header: 'Mã HV', accessor: 'id' as keyof Student, sortable: true },
        { header: 'Họ tên', accessor: 'name' as keyof Student, sortable: true },
        { header: 'Email', accessor: 'email' as keyof Student, sortable: true },
        { header: 'Phụ huynh', accessor: 'parentName' as keyof Student, sortable: true },
    ];

    const reportColumns = [
        { header: 'Ngày', accessor: 'date' as keyof ProgressReport, sortable: true },
        { header: 'Học viên', accessor: (item: ProgressReport) => getStudentName(item.studentId) },
        { header: 'Điểm', accessor: 'score' as keyof ProgressReport, sortable: true },
        { header: 'Nhận xét', accessor: 'comments' as keyof ProgressReport },
    ];

    const handleAddReport = async (reportData: Omit<ProgressReport, 'id'>) => {
        try {
            await addProgressReport(reportData);
            toast.success(`Đã thêm báo cáo cho học viên ${getStudentName(reportData.studentId)}.`);
            setReportModalOpen(false);
        } catch (error) {
            toast.error('Đã xảy ra lỗi. Vui lòng thử lại.');
        }
    };

    const handleEdit = () => {
        history.push({ pathname: ROUTES.CLASSES, state: { editClassId: cls.id, returnTo: `/class/${cls.id}` } });
    };

    const handleDelete = async () => {
        try {
            await deleteClass(cls.id);
            toast.success(`Đã xoá lớp học ${cls.name}`);
            history.replace(ROUTES.CLASSES, {});
        } catch (error) {
            toast.error('Lỗi khi xoá lớp học.');
        }
        setDeleteConfirmOpen(false);
    };

    const dayMap: Record<string, string> = {
        'Monday': 'Thứ Hai', 'Tuesday': 'Thứ Ba', 'Wednesday': 'Thứ Tư', 'Thursday': 'Thứ Năm',
        'Friday': 'Thứ Sáu', 'Saturday': 'Thứ Bảy', 'Sunday': 'Chủ Nhật'
    };

    const TabButton: React.FC<{ tabId: ClassDetailTab; children: React.ReactNode }> = ({ tabId, children }) => (
        <button
            onClick={() => setActiveTab(tabId)}
            className={`px-4 py-2 font-semibold transition-colors duration-200 border-b-2 whitespace-nowrap ${activeTab === tabId ? 'border-primary text-primary' : 'border-transparent text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 hover:border-slate-300 dark:hover:border-slate-600'}`}
        >
            {children}
        </button>
    );

    return (
        <div className="space-y-6">
            <div className="card-base">
                <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                    <div className="flex-grow">
                        <h1 className="text-3xl font-bold">{cls.name}</h1>
                        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 mt-4 text-sm">
                            <span className="bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-full font-mono font-semibold">ID: {cls.id}</span>
                            <span className="bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300 px-3 py-1 rounded-full font-semibold">Môn: {cls.subject}</span>
                            <span className="bg-indigo-100 text-indigo-800 dark:bg-indigo-900/50 dark:text-indigo-300 px-3 py-1 rounded-full font-semibold">GV: {teacherNames}</span>
                        </div>
                        <div className="mt-4 text-sm text-gray-600 dark:text-gray-300 flex flex-wrap gap-x-4 gap-y-1">
                            {(cls.schedule || []).map((s, i) => (
                                <div key={i} className="font-semibold">{`${dayMap[s.dayOfWeek]}: ${s.startTime} - ${s.endTime}`}</div>
                            ))}
                        </div>
                    </div>
                    {canManage && (
                        <div className="flex items-center gap-2 flex-shrink-0 w-full sm:w-auto">
                            <Button variant="secondary" onClick={handleEdit} className="flex-1 sm:flex-none">{ICONS.edit} Sửa</Button>
                            <Button variant="danger" onClick={() => setDeleteConfirmOpen(true)} className="flex-1 sm:flex-none">{ICONS.delete} Xóa</Button>
                        </div>
                    )}
                </div>
            </div>

            <div className="border-b border-gray-200 dark:border-gray-700">
                <nav className="-mb-px flex space-x-2 overflow-x-auto" aria-label="Tabs">
                    <TabButton tabId="students">Học viên ({classStudents.length})</TabButton>
                    <TabButton tabId="attendance">Điểm danh</TabButton>
                    <TabButton tabId="reports">Báo cáo ({classProgressReports.length})</TabButton>
                    <TabButton tabId="announcements">Thông báo</TabButton>
                </nav>
            </div>

            <div className="card-base">
                {activeTab === 'students' && (
                    <>
                        <h2 className="text-xl font-semibold mb-4">Danh sách học viên</h2>
                        <div className="hidden md:block">
                            <Table<Student>
                                columns={studentColumns}
                                data={sortedClassStudents}
                                sortConfig={studentSortConfig}
                                onSort={handleStudentSort}
                            />
                        </div>
                         <div className="md:hidden space-y-4">
                            {sortedClassStudents.map(student => (
                                <ListItemCard
                                    key={student.id}
                                    title={<Link to={`/student/${student.id}`} className="font-semibold text-primary hover:underline">{student.name}</Link>}
                                    details={[
                                        { label: "Mã HV", value: student.id },
                                        { label: "Phụ huynh", value: student.parentName }
                                    ]}
                                />
                            ))}
                        </div>
                    </>
                )}

                 {activeTab === 'attendance' && (
                    <AttendanceTab cls={cls} attendance={classAttendance} />
                )}

                {activeTab === 'reports' && (
                    <>
                         <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                            <h2 className="text-xl font-semibold">Sổ liên lạc - Báo cáo Tiến độ</h2>
                            <div className="relative group w-full md:w-auto">
                                <Button 
                                    onClick={() => setReportModalOpen(true)}
                                    disabled={classStudents.length === 0 || role === UserRole.VIEWER}
                                    className="w-full"
                                >
                                    {ICONS.plus} Thêm Báo cáo
                                </Button>
                                {classStudents.length === 0 && (
                                     <div className="absolute bottom-full mb-2 w-max px-2 py-1 bg-gray-700 text-white text-xs rounded-md opacity-0 group-hover:opacity-100 transition-opacity">
                                        Cần có học viên trong lớp để thêm báo cáo
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="hidden md:block">
                            <Table<ProgressReport>
                                columns={reportColumns}
                                data={sortedClassProgressReports}
                                sortConfig={reportSortConfig}
                                onSort={handleReportSort}
                            />
                        </div>
                         <div className="md:hidden space-y-4">
                            {sortedClassProgressReports.map(report => (
                                 <ListItemCard
                                    key={report.id}
                                    title={<div className="flex justify-between w-full"><span>{getStudentName(report.studentId)}</span><span className="text-primary font-bold">{report.score}/10</span></div>}
                                    details={[
                                        { label: "Ngày", value: report.date },
                                        { label: "Nhận xét", value: <i className="block whitespace-normal">{report.comments}</i> },
                                    ]}
                                />
                            ))}
                         </div>
                    </>
                )}

                {activeTab === 'announcements' && (
                    <AnnouncementsTab classId={cls.id} />
                )}
            </div>

            <Modal isOpen={isReportModalOpen} onClose={() => setReportModalOpen(false)} title="Thêm Báo cáo Tiến độ">
                <ProgressReportForm
                    classStudents={classStudents}
                    classId={cls.id}
                    creatorId={user.id}
                    onSubmit={handleAddReport}
                    onCancel={() => setReportModalOpen(false)}
                />
            </Modal>
            <ConfirmationModal
                isOpen={deleteConfirmOpen}
                onClose={() => setDeleteConfirmOpen(false)}
                onConfirm={handleDelete}
                title="Xác nhận Xóa Lớp học"
                message={
                     <p>
                        Bạn có chắc chắn muốn xóa lớp học <strong>{cls?.name}</strong>?
                        <br/><br/>
                        <span className="font-bold text-red-500">CẢNH BÁO:</span> Mọi dữ liệu điểm danh và báo cáo tiến độ của lớp này cũng sẽ bị xóa.
                    </p>
                }
            />
        </div>
    );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useParams, useHistory, useLocation } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useAuth } from '../hooks/useAuth';
import { useToast } from '../hooks/useToast';
import { AttendanceRecord, AttendanceStatus, PersonStatus, UserRole, Student } from '../types';
import { Button } from '../components/common/Button';
import { ICONS } from '../constants';
import { ConfirmationModal } from '../components/common/ConfirmationModal';

export const AttendanceScreen: React.FC = () => {
    const { classId, date } = useParams<{ classId: string; date: string }>();
    const history = useHistory();
    const location = useLocation<{ returnTo?: string; defaultTab?: string }>();
    const { state, updateAttendance, deleteAttendanceForDate } = useData();
    const { toast } = useToast();
    const { role } = useAuth();
    const { classes, students, attendance } = state;

    const [attendanceData, setAttendanceData] = useState<Map<string, AttendanceStatus>>(new Map());
    const [isLoading, setIsLoading] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [confirmDeleteModalOpen, setConfirmDeleteModalOpen] = useState(false);
    const [unmarkedConfirmModalOpen, setUnmarkedConfirmModalOpen] = useState(false);


    const isViewer = role === UserRole.VIEWER;
    const canTakeAttendance = !isViewer;

    const cls = classes.find(c => c.id === classId);

    // Logic updated to include both currently active students AND any student who has a record for this day
    // This prevents data loss for inactive students when editing past records
    const classStudents = useMemo(() => {
        if (!cls) return [];

        const getLastName = (fullName: string) => {
            if (!fullName) return '';
            const parts = fullName.trim().split(/\s+/);
            return parts[parts.length - 1];
        };

        // 1. Students currently enrolled and active
        const activeEnrolledStudents = students.filter(s => cls.studentIds.includes(s.id) && s.status === PersonStatus.ACTIVE);

        // 2. Students who have attendance records for this specific date/class (history)
        // This ensures we don't lose records of students who dropped out but attended this day
        const recordedStudentIds = attendance
            .filter(a => a.classId === classId && a.date === date)
            .map(a => a.studentId);

        const recordedStudents = students.filter(s => recordedStudentIds.includes(s.id));

        // Merge and remove duplicates
        const uniqueStudentsMap = new Map<string, Student>();
        activeEnrolledStudents.forEach(s => uniqueStudentsMap.set(s.id, s));
        recordedStudents.forEach(s => uniqueStudentsMap.set(s.id, s));

        const combinedStudents = Array.from(uniqueStudentsMap.values());

        return combinedStudents.sort((a, b) => {
            const lastNameA = getLastName(a.name);
            const lastNameB = getLastName(b.name);

            const lastNameComparison = lastNameA.localeCompare(lastNameB, 'vi');

            if (lastNameComparison !== 0) {
                return lastNameComparison;
            }

            return a.name.localeCompare(b.name, 'vi');
        });
    }, [cls, students, attendance, classId, date]);

    const hasExistingData = useMemo(() => {
        return attendance.some(a => a.classId === classId && a.date === date);
    }, [attendance, classId, date]);

    const attendanceCounts = useMemo(() => {
        if (!classId || !date) return new Map<string, number>();

        const monthStr = date.substring(0, 7);

        const counts = new Map<string, number>();
        const classAttendanceRecords = attendance.filter(a => a.classId === classId);

        classStudents.forEach(student => {
            const studentMonthlyAttendance = classAttendanceRecords.filter(a =>
                a.studentId === student.id &&
                a.date.startsWith(monthStr) &&
                (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
            );
            counts.set(student.id, studentMonthlyAttendance.length);
        });

        return counts;
    }, [attendance, classId, date, classStudents]);


    useEffect(() => {
        const initialData = new Map<string, AttendanceStatus>();
        classStudents.forEach(student => {
            const record = attendance.find(a => a.classId === classId && a.studentId === student.id && a.date === date);
            initialData.set(student.id, record ? record.status : AttendanceStatus.UNMARKED);
        });
        setAttendanceData(initialData);
    }, [classId, date, attendance, classStudents]);

    const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
        if (!canTakeAttendance) return;
        setAttendanceData(prev => new Map(prev).set(studentId, status));
    };

    const handleBulkChange = (status: AttendanceStatus) => {
        if (!canTakeAttendance) return;
        const newMap = new Map<string, AttendanceStatus>();
        classStudents.forEach(student => {
            newMap.set(student.id, status);
        });
        setAttendanceData(newMap);
    };

    const handleNavigateBack = () => {
        const returnTo = location.state?.returnTo || `/class/${classId}`;
        const returnState = location.state?.defaultTab ? { defaultTab: location.state.defaultTab } : {};
        history.push({ pathname: returnTo, state: returnState });
    };

    const proceedWithSave = useCallback(async () => {
        if (!canTakeAttendance || !classId || !date) return;

        setIsLoading(true);
        const newRecords: AttendanceRecord[] = [];
        for (const [studentId, status] of attendanceData.entries()) {
            if (status !== AttendanceStatus.UNMARKED) {
                const existingRecord = attendance.find(a => a.classId === classId && a.studentId === studentId && a.date === date);
                newRecords.push({
                    id: existingRecord?.id || `A-${Date.now()}-${studentId}`,
                    classId: classId!,
                    studentId,
                    date: date!,
                    status,
                });
            }
        }
        try {
            await updateAttendance(newRecords);
            toast.success('Đã lưu điểm danh thành công!');
            handleNavigateBack();
        } catch (error) {
            toast.error('Lỗi khi lưu điểm danh. Vui lòng thử lại.');
        } finally {
            setIsLoading(false);
            setUnmarkedConfirmModalOpen(false);
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [attendanceData, classId, date, canTakeAttendance, updateAttendance, toast, history, location.state]);

    const handleSubmit = () => {
        const unmarkedCount = Array.from(attendanceData.values()).filter(status => status === AttendanceStatus.UNMARKED).length;
        if (unmarkedCount > 0) {
            setUnmarkedConfirmModalOpen(true);
        } else {
            proceedWithSave();
        }
    };


    const handleDelete = async () => {
        if (!classId || !date || !canTakeAttendance) return;
        setIsDeleting(true);
        try {
            await deleteAttendanceForDate({ classId, date });
            toast.success(`Đã xóa điểm danh ngày ${date} cho lớp ${cls?.name}.`);
            handleNavigateBack();
        } catch (error) {
            toast.error('Lỗi khi xóa điểm danh.');
        } finally {
            setIsDeleting(false);
            setConfirmDeleteModalOpen(false);
        }
    };

    if (!cls) return <div className="p-6">Lớp học không tồn tại.</div>;

    const StatusButton: React.FC<{current: AttendanceStatus, target: AttendanceStatus, onClick: () => void, label: string, color: string, icon: React.ReactElement<React.SVGProps<SVGSVGElement>>}> = ({current, target, onClick, label, color, icon}) => (
        <button
            onClick={onClick}
            title={label}
            disabled={!canTakeAttendance}
            className={`p-3 sm:px-3 sm:py-2 rounded-lg transition-all duration-200 flex items-center justify-center gap-1.5 font-semibold text-sm flex-1 ${current === target ? `${color} text-white shadow-md ring-2 ring-offset-1 ring-offset-white dark:ring-offset-gray-800 ring-${color.split('-')[1]}-400` : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'} disabled:opacity-50 disabled:cursor-not-allowed`}
        >
            {React.cloneElement(icon, {width: 20, height: 20})}
            <span className="hidden sm:inline">{label}</span>
        </button>
    );

    return (
        <>
            <div className="flex flex-col h-full">
                <div className="flex-1 overflow-y-auto p-4 md:p-6">
                    <div className="mb-6">
                         <Button variant="secondary" onClick={handleNavigateBack} className="mb-4">
                            {ICONS.chevronLeft} Quay lại
                        </Button>
                        <h1 className="text-2xl md:text-3xl font-bold">Điểm danh lớp {cls.name}</h1>
                        <p className="text-gray-600 dark:text-gray-300">Ngày: {new Date(date || '').toLocaleDateString('vi-VN')}</p>
                    </div>

                    {classStudents.length > 0 && canTakeAttendance && (
                        <div className="mb-4 p-3 bg-blue-50 dark:bg-gray-700 rounded-lg text-blue-800 dark:text-blue-200 text-sm">
                           <p className="mb-2 font-semibold">Thao tác nhanh:</p>
                           <div className="flex gap-2 w-full overflow-x-auto pb-1">
                                <Button size="sm" variant="secondary" onClick={() => handleBulkChange(AttendanceStatus.PRESENT)} disabled={!canTakeAttendance} className="whitespace-nowrap">Tất cả có mặt</Button>
                                <Button size="sm" onClick={() => handleBulkChange(AttendanceStatus.LATE)} disabled={!canTakeAttendance} className="bg-yellow-500 hover:bg-yellow-600 focus:ring-yellow-400 text-white whitespace-nowrap">Tất cả đi muộn</Button>
                                <Button size="sm" variant="danger" onClick={() => handleBulkChange(AttendanceStatus.ABSENT)} disabled={!canTakeAttendance} className="whitespace-nowrap">Tất cả vắng</Button>
                           </div>
                        </div>
                    )}

                    <div className="space-y-3 pb-20">
                        {classStudents.length > 0 ? (
                            classStudents.map(student => {
                                const isInactive = student.status !== PersonStatus.ACTIVE || !cls.studentIds.includes(student.id);
                                return (
                                    <div key={student.id} className={`bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border flex flex-col md:flex-row items-stretch md:items-center gap-4 ${isInactive ? 'border-orange-200 dark:border-orange-900/30 bg-orange-50/30 dark:bg-orange-900/10' : 'border-gray-100 dark:border-gray-700'}`}>
                                        <div className="flex-grow flex justify-between items-start">
                                            <div>
                                                <span className={`font-bold text-base md:text-lg ${isInactive ? 'text-gray-500' : ''}`}>
                                                    {student.name}
                                                    {isInactive && <span className="text-xs text-orange-500 font-normal ml-2">(Đã nghỉ / Khác)</span>}
                                                </span>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <span className="text-xs font-bold bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-200 px-2 py-0.5 rounded-full">
                                                        Tháng này: {attendanceCounts.get(student.id) || 0} buổi
                                                    </span>
                                                    {attendanceData.get(student.id) === AttendanceStatus.UNMARKED && (
                                                        <span className="text-xs font-bold bg-gray-200 text-gray-700 dark:bg-gray-600 dark:text-gray-200 px-2 py-0.5 rounded-full animate-pulse">
                                                            Chưa điểm danh
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex gap-2 w-full md:w-auto">
                                            <StatusButton current={attendanceData.get(student.id)!} target={AttendanceStatus.PRESENT} onClick={() => handleStatusChange(student.id, AttendanceStatus.PRESENT)} label="Có mặt" color="bg-green-600" icon={<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>} />
                                            <StatusButton current={attendanceData.get(student.id)!} target={AttendanceStatus.LATE} onClick={() => handleStatusChange(student.id, AttendanceStatus.LATE)} label="Trễ" color="bg-yellow-500" icon={<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>} />
                                            <StatusButton current={attendanceData.get(student.id)!} target={AttendanceStatus.ABSENT} onClick={() => handleStatusChange(student.id, AttendanceStatus.ABSENT)} label="Vắng" color="bg-red-500" icon={<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>} />
                                        </div>
                                    </div>
                                );
                            })
                        ) : (
                            <div className="text-center p-8 card-base">
                                <p className="text-gray-500 dark:text-gray-400">Không có học viên nào đang hoạt động trong lớp này để điểm danh.</p>
                            </div>
                        )}
                    </div>
                </div>

                 <div className="p-4 bg-white dark:bg-gray-800 border-t dark:border-gray-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] sticky bottom-0 z-20 pb-safe">
                    <div className="flex items-center justify-between gap-4">
                        <div className="flex-1">
                            {hasExistingData && canTakeAttendance && (
                                <Button
                                    onClick={() => setConfirmDeleteModalOpen(true)}
                                    variant="danger"
                                    isLoading={isDeleting}
                                    disabled={isLoading}
                                    className="w-full sm:w-auto"
                                    title="Xóa Điểm danh"
                                >
                                    {ICONS.delete}
                                    <span className="hidden sm:inline ml-2">Xóa Dữ liệu</span>
                                </Button>
                            )}
                        </div>

                        <div className="flex-1 flex justify-end">
                            {classStudents.length > 0 && canTakeAttendance && (
                                <Button
                                    onClick={handleSubmit}
                                    className="w-full sm:w-auto min-w-[120px] py-3 text-base"
                                    isLoading={isLoading}
                                    disabled={isDeleting}
                                >
                                    <span className="mr-2">{ICONS.check}</span>
                                    Lưu
                                </Button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
            <ConfirmationModal
                isOpen={confirmDeleteModalOpen}
                onClose={() => setConfirmDeleteModalOpen(false)}
                onConfirm={handleDelete}
                title="Xác nhận Xóa Điểm danh"
                message={`Bạn có chắc chắn muốn xóa toàn bộ dữ liệu điểm danh cho lớp ${cls?.name} vào ngày ${date}? Hành động này không thể hoàn tác.`}
            />
             <ConfirmationModal
                isOpen={unmarkedConfirmModalOpen}
                onClose={() => setUnmarkedConfirmModalOpen(false)}
                onConfirm={proceedWithSave}
                title="Xác nhận Lưu Điểm danh"
                message="Có học viên chưa được điểm danh. Nếu tiếp tục, những học viên này sẽ không có bản ghi điểm danh cho ngày hôm nay. Bạn có chắc chắn muốn lưu?"
                confirmButtonText="Vẫn lưu"
                confirmButtonVariant="primary"
            />
        </>
    );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useParams, Link, useHistory } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useAuth } from '../hooks/useAuth';
import { useToast } from '../hooks/useToast';
import { Table, SortConfig } from '../components/common/Table';
import { Button } from '../components/common/Button';
import { Modal } from '../components/common/Modal';
import { ICONS, ROUTES } from '../constants';
import { Transaction, ProgressReport, PersonStatus, TransactionType, Class, AttendanceStatus, UserRole, AttendanceRecord } from '../types';
import { CurrencyInput } from '../components/common/CurrencyInput';
import { ListItemCard } from '../components/common/ListItemCard';
import { ConfirmationModal } from '../components/common/ConfirmationModal';
import { PaymentModal } from '../components/finance/PaymentModal';

const transactionTypeMap: Record<TransactionType, string> = {
    [TransactionType.INVOICE]: 'Hóa đơn',
    [TransactionType.PAYMENT]: 'Thanh toán',
    [TransactionType.ADJUSTMENT_CREDIT]: 'Điều chỉnh Ghi có',
    [TransactionType.ADJUSTMENT_DEBIT]: 'Phí khác',
};

const AdjustmentForm: React.FC<{
    transactionToEdit?: Transaction;
    onSubmit: (data: { sign: 'CREDIT' | 'DEBIT'; amount: number; date: string; description: string; }) => void;
    onCancel: () => void;
}> = ({ transactionToEdit, onSubmit, onCancel }) => {
    const [sign, setSign] = useState<'CREDIT' | 'DEBIT'>(transactionToEdit && transactionToEdit.amount < 0 ? 'DEBIT' : 'CREDIT');
    const [amount, setAmount] = useState(transactionToEdit ? Math.abs(transactionToEdit.amount) : 0);
    const [description, setDescription] = useState(transactionToEdit?.description || '');
    const [date, setDate] = useState(transactionToEdit?.date || new Date().toISOString().split('T')[0]);

    const descriptionInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        descriptionInputRef.current?.focus();
    }, []);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit({ sign, amount, date, description });
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-4">
             <div>
                <label className="block text-sm font-medium mb-2">Loại giao dịch</label>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                    <label className={`flex items-center p-3 rounded-md border-2 cursor-pointer transition-all ${sign === 'CREDIT' ? 'border-primary bg-indigo-50 dark:bg-indigo-900/20' : 'border-gray-300 dark:border-gray-600'}`}>
                        <input
                            type="radio"
                            name="sign"
                            value="CREDIT"
                            checked={sign === 'CREDIT'}
                            onChange={() => setSign('CREDIT')}
                            className="h-4 w-4 text-primary focus:ring-primary-dark"
                        />
                        <span className="ml-3 text-sm font-medium">Thanh toán / Ghi có (Tăng số dư)</span>
                    </label>
                    <label className={`flex items-center p-3 rounded-md border-2 cursor-pointer transition-all ${sign === 'DEBIT' ? 'border-primary bg-indigo-50 dark:bg-indigo-900/20' : 'border-gray-300 dark:border-gray-600'}`}>
                        <input
                            type="radio"
                            name="sign"
                            value="DEBIT"
                            checked={sign === 'DEBIT'}
                            onChange={() => setSign('DEBIT')}
                            className="h-4 w-4 text-primary focus:ring-primary-dark"
                        />
                        <span className="ml-3 text-sm font-medium">Phí / Ghi nợ (Giảm số dư)</span>
                    </label>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium">Mô tả</label>
                <input
                    ref={descriptionInputRef}
                    type="text"
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                    className="form-input mt-1"
                    required
                />
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium">Số tiền (VND)</label>
                    <CurrencyInput value={amount} onChange={setAmount} className="form-input mt-1" required />
                </div>
                <div>
                    <label className="block text-sm font-medium">Ngày</label>
                    <input type="date" value={date} onChange={e => setDate(e.target.value)} className="form-input mt-1" required />
                </div>
            </div>

            <div className="flex justify-end space-x-4 pt-4 border-t dark:border-gray-700">
                <Button type="button" variant="secondary" onClick={onCancel}>Hủy</Button>
                <Button type="submit">Lưu Giao dịch</Button>
            </div>
        </form>
    );
};

const AttendanceSummaryWidget: React.FC<{ 
    studentId: string; 
    enrolledClasses: Class[];
    filterMonth: number;
    filterYear: number;
}> = ({ studentId, enrolledClasses, filterMonth, filterYear }) => {
    const { state } = useData();

    // Filter attendance records based on student ID and selected month/year
    const filteredAttendance = useMemo(() => {
        return state.attendance.filter(a => {
            if (a.studentId !== studentId) return false;
            if (filterMonth === 0) return true; // Show all if month is 0 (All)

            const recordDate = new Date(a.date);
            return recordDate.getMonth() + 1 === filterMonth && recordDate.getFullYear() === filterYear;
        });
    }, [state.attendance, studentId, filterMonth, filterYear]);

    const summary = useMemo(() => {
        return enrolledClasses.map(cls => {
            const classAttendance = filteredAttendance.filter(a => a.classId === cls.id);
            const present = classAttendance.filter(a => a.status === AttendanceStatus.PRESENT).length;
            const absent = classAttendance.filter(a => a.status === AttendanceStatus.ABSENT).length;
            const late = classAttendance.filter(a => a.status === AttendanceStatus.LATE).length;
            const total = classAttendance.length;
            const percentage = total > 0 ? (((present + late) / total) * 100).toFixed(0) : 'N/A';

            const isEnrolled = cls.studentIds.includes(studentId);
            // Show class if: 
            // 1. Currently enrolled (always show to see 0 attendance if new)
            // 2. OR has data for the selected month (historical class)
            const shouldShow = isEnrolled || total > 0 || filterMonth === 0;

            return {
                classId: cls.id,
                className: cls.name,
                isEnrolled,
                present,
                absent,
                late,
                percentage,
                shouldShow
            };
        }).filter(s => s.shouldShow);
    }, [filteredAttendance, enrolledClasses, filterMonth, studentId]);

    if (summary.length === 0) {
        return (
            <div className="card-base text-center text-gray-500 py-8">
                Không có dữ liệu điểm danh cho giai đoạn này.
            </div>
        );
    }

    return (
        <div className="card-base">
            <h2 className="text-xl font-semibold mb-4">Thống kê Chuyên cần {filterMonth === 0 ? '(Tất cả)' : `(Tháng ${filterMonth}/${filterYear})`}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {summary.map(s => (
                    <div key={s.classId} className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                        <h3 className="font-semibold text-primary">
                            {s.className}
                            {!s.isEnrolled && <span className="text-xs text-gray-500 font-normal ml-2">(Lớp cũ)</span>}
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-sm mt-2 text-center">
                            <div>
                                <p className="font-bold text-lg text-green-600">{s.present}</p>
                                <p className="text-xs text-gray-500">Có mặt</p>
                            </div>
                             <div>
                                <p className="font-bold text-lg text-red-600">{s.absent}</p>
                                <p className="text-xs text-gray-500">Vắng</p>
                            </div>
                            <div>
                                <p className="font-bold text-lg text-yellow-600">{s.late}</p>
                                <p className="text-xs text-gray-500">Trễ</p>
                            </div>
                            <div>
                                <p className="font-bold text-lg text-blue-600">{s.percentage}%</p>
                                <p className="text-xs text-gray-500">Tỷ lệ</p>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};


export const StudentDetailScreen: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const { state, addAdjustment, updateTransaction, deleteTransaction, updateAttendance, deleteStudent } = useData();
    const { toast } = useToast();
    const { role } = useAuth();
    const history = useHistory();
    const { students, classes, progressReports, transactions, attendance } = state;

    const [activeTab, setActiveTab] = useState('overview');
    const [transactionModal, setTransactionModal] = useState<{ open: boolean, item?: Transaction }>({ open: false });
    const [paymentModalOpen, setPaymentModalOpen] = useState(false);
    const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean, item?: Transaction }>({ open: false });
    const [attendanceLogModal, setAttendanceLogModal] = useState<{ isOpen: boolean; classId: string | null; className: string | null }>({ isOpen: false, classId: null, className: null });
    const [deleteStudentConfirmOpen, setDeleteStudentConfirmOpen] = useState(false);

    // Filter State
    const [filterMonth, setFilterMonth] = useState(new Date().getMonth() + 1);
    const [filterYear, setFilterYear] = useState(new Date().getFullYear());

    const canManage = role !== UserRole.VIEWER;
    const student = useMemo(() => students.find(s => s.id === id), [students, id]);

    // Updated logic to include both currently enrolled classes AND classes with attendance history
    const relatedClasses = useMemo(() => {
        if (!id) return [];
        const relatedClassIds = new Set<string>();

        // 1. Currently enrolled classes
        classes.forEach(c => {
            if (c.studentIds.includes(id)) {
                relatedClassIds.add(c.id);
            }
        });

        // 2. Classes with attendance records
        attendance.forEach(a => {
            if (a.studentId === id) {
                relatedClassIds.add(a.classId);
            }
        });

        return classes.filter(c => relatedClassIds.has(c.id));
    }, [classes, attendance, id]);

    const studentProgressReports = useMemo(() => 
        progressReports.filter(pr => pr.studentId === id),
    [progressReports, id]);

    const studentTransactions = useMemo(() => 
        transactions.filter(t => t.studentId === id),
    [transactions, id]);

    const [transactionSortConfig, setTransactionSortConfig] = useState<SortConfig<Transaction & { endingBalance: number }> | null>({ key: 'date', direction: 'descending' });

    const transactionsWithEndingBalance = useMemo(() => {
        if (!studentTransactions) return [];
        let runningBalance = 0;
        return [...studentTransactions]
            .sort((a, b) => {
                const dateComparison = new Date(a.date).getTime() - new Date(b.date).getTime();
                if (dateComparison !== 0) return dateComparison;
                return a.id.localeCompare(b.id);
            })
            .map(t => {
                runningBalance += t.amount;
                return { ...t, endingBalance: runningBalance };
            });
    }, [studentTransactions]);

    const sortedTransactionsWithEndingBalance = useMemo(() => {
        let sortableItems = [...transactionsWithEndingBalance];
        if (transactionSortConfig) {
            sortableItems.sort((a, b) => {
                if (transactionSortConfig.key === 'date') {
                    const aDate = new Date(a.date).getTime();
                    const bDate = new Date(b.date).getTime();
                    if (aDate < bDate) return transactionSortConfig.direction === 'ascending' ? -1 : 1;
                    if (aDate > bDate) return transactionSortConfig.direction === 'ascending' ? 1 : -1;
                    // If dates are also the same, use ID as a tie-breaker for stable sort
                    return transactionSortConfig.direction === 'ascending' ? a.id.localeCompare(b.id) : b.id.localeCompare(a.id);
                }

                const aValue = a[transactionSortConfig.key];
                const bValue = b[transactionSortConfig.key];

                if (aValue == null || bValue == null) return 0;

                if (aValue < bValue) return transactionSortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return transactionSortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [transactionsWithEndingBalance, transactionSortConfig]);

    const handleTransactionSort = (key: keyof (Transaction & { endingBalance: number })) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (transactionSortConfig && transactionSortConfig.key === key && transactionSortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setTransactionSortConfig({ key, direction });
    };

    const [reportSortConfig, setReportSortConfig] = useState<SortConfig<ProgressReport> | null>({ key: 'date', direction: 'descending' });
    const handleReportSort = (key: keyof ProgressReport) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (reportSortConfig && reportSortConfig.key === key && reportSortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setReportSortConfig({ key, direction });
    };
    const sortedStudentProgressReports = useMemo(() => {
        let sortableItems = [...studentProgressReports];
        if (reportSortConfig) {
            sortableItems.sort((a, b) => {
                const aValue = a[reportSortConfig.key];
                const bValue = b[reportSortConfig.key];
                if (aValue < bValue) return reportSortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return reportSortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [studentProgressReports, reportSortConfig]);

    const attendanceLogForModal = useMemo(() => {
        if (!attendanceLogModal.classId || !student) return [];
        return attendance
            .filter(a => {
                if (a.studentId !== student.id || a.classId !== attendanceLogModal.classId) return false;
                if (filterMonth === 0) return true;
                const recordDate = new Date(a.date);
                return recordDate.getMonth() + 1 === filterMonth && recordDate.getFullYear() === filterYear;
            })
            .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [attendance, student, attendanceLogModal.classId, filterMonth, filterYear]);

    const handleAttendanceChange = async (recordToUpdate: AttendanceRecord, newStatus: AttendanceStatus) => {
        if (recordToUpdate.status === newStatus) return;

        const allRecordsForDay = attendance.filter(
            a => a.classId === recordToUpdate.classId && a.date === recordToUpdate.date && a.studentId !== recordToUpdate.studentId
        );

        const updatedRecord: AttendanceRecord = {
            ...recordToUpdate,
            status: newStatus,
        };

        const newRecordsForDay = [...allRecordsForDay, updatedRecord];

        try {
            await updateAttendance(newRecordsForDay);
            toast.success(`Đã cập nhật điểm danh ngày ${recordToUpdate.date}.`);
        } catch (error) {
            toast.error('Lỗi khi cập nhật điểm danh.');
        }
    };

