                    isOpen={attendanceLogModal.isOpen} 
                    onClose={() => setAttendanceLogModal({ isOpen: false, classId: null, className: null })}
                    title={`Lịch sử điểm danh: ${attendanceLogModal.className} ${filterMonth === 0 ? '(Tất cả)' : `(Tháng ${filterMonth}/${filterYear})`}`}
                >
                    <div className="space-y-3 max-h-[60vh] overflow-y-auto">
                        {attendanceLogForModal.length > 0 ? (
                            attendanceLogForModal.map(record => (
                                <div key={record.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-700/50 rounded-md">
                                    <p className="font-semibold">{record.date}</p>
                                    {canManage ? (
                                        <select
                                            value={record.status}
                                            onChange={(e) => handleAttendanceChange(record, e.target.value as AttendanceStatus)}
                                            className="form-select py-1 px-2 text-sm w-33"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <option value={AttendanceStatus.PRESENT}>Có mặt</option>
                                            <option value={AttendanceStatus.ABSENT}>Vắng</option>
                                            <option value={AttendanceStatus.LATE}>Trễ</option>
                                        </select>
                                    ) : (
                                        getStatusBadge(record.status)
                                    )}
                                </div>
                            ))
                        ) : (
                            <p className="text-center py-4 text-gray-500">Chưa có dữ liệu điểm danh phù hợp.</p>
                        )}
                    </div>
                </Modal>
                 <ConfirmationModal
                    isOpen={deleteStudentConfirmOpen}
                    onClose={() => setDeleteStudentConfirmOpen(false)}
                    onConfirm={handleDelete}
                    title="Xác nhận Xóa Học viên"
                    message={
                        <p>
                            Bạn có chắc chắn muốn xoá học viên <strong>{student?.name}</strong>?
                            <br /><br />
                            <span className="font-bold text-red-500">CẢNH BÁO:</span> Toàn bộ dữ liệu học phí, điểm danh và báo cáo của học viên này cũng sẽ bị XOÁ VĨNH VIỄN.
                        </p>
                    }
                />
            </div>
        </>
    );
};

export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  MANAGER = 'MANAGER',
  ACCOUNTANT = 'ACCOUNTANT',
  PARENT = 'PARENT',
  VIEWER = 'VIEWER',
}

export enum PersonStatus {
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE',
}

export enum AttendanceStatus {
  PRESENT = 'PRESENT',
  ABSENT = 'ABSENT',
  LATE = 'LATE',
  UNMARKED = 'UNMARKED',
}

export enum FeeType {
  PER_SESSION = 'PER_SESSION',
  MONTHLY = 'MONTHLY',
  PER_COURSE = 'PER_COURSE',
}

export enum SalaryType {
  PER_SESSION = 'PER_SESSION',
  MONTHLY = 'MONTHLY',
}

export interface BasePerson {
  id: string;
  name: string;
  email?: string;
  phone: string;
  address: string;
  status: PersonStatus;
  createdAt: string;
  password?: string;
  gender?: 'Nam' | 'Nữ' | 'Khác';
}

export interface Student extends BasePerson {
  dob: string;
  parentName: string;
  email: string;
  balance: number; // Student's account balance. Positive = credit, Negative = debt.
}

export interface Teacher extends BasePerson {
  dob: string;
  qualification: string;
  subject: string;
  role: UserRole.TEACHER;
  salaryType: SalaryType;
  rate: number; // Amount per hour or fixed monthly salary
}

export interface Staff extends BasePerson {
  dob: string;
  position: string;
  role: UserRole.MANAGER | UserRole.ACCOUNTANT;
}

export interface ClassFee {
  type: FeeType;
  amount: number;
}

export interface ClassSchedule {
  dayOfWeek: 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday' | 'Saturday' | 'Sunday';
  startTime: string; // "HH:MM"
  endTime: string; // "HH:MM"
}

export interface Class {
  id: string;
  name: string;
  teacherIds: string[];
  subject: string;
  schedule: ClassSchedule[];
  studentIds: string[];
  fee: ClassFee;
}

export interface AttendanceRecord {
  id: string;
  classId: string;
  studentId: string;
  date: string; // "YYYY-MM-DD"
  status: AttendanceStatus;
}

export interface Invoice {
  id: string;
  studentId: string;
  studentName: string;
  month: string; // e.g., "2024-07"
  amount: number;
  details: string;
  status: 'PAID' | 'UNPAID' | 'CANCELLED';
  generatedDate: string; // "YYYY-MM-DD"
  paidDate: string | null; // "YYYY-MM-DD"
}

export enum TransactionType {
    INVOICE = 'INVOICE', // A generated bill (debit)
    PAYMENT = 'PAYMENT', // A payment received (credit)
    ADJUSTMENT_CREDIT = 'ADJUSTMENT_CREDIT', // Manual credit (e.g., refund, bonus)
    ADJUSTMENT_DEBIT = 'ADJUSTMENT_DEBIT', // Manual debit (e.g., fee, penalty)
}

export interface Transaction {
    id: string;
    studentId: string;
    date: string; // "YYYY-MM-DD"
    type: TransactionType;
    description: string;
    amount: number; // Positive for credits/payments, negative for debits/invoices
    relatedInvoiceId?: string;
}


export interface ProgressReport {
  id: string;
  classId: string;
  studentId: string;
